import { useCallback, useEffect, useRef, useState } from 'react';
import confetti from 'canvas-confetti';
import Hud, { Toast } from './components/Hud';
import { Menu, PauseMenu, GameOver, UpgradePick } from './components/Screens';
import { Game, HudState } from './game/engine';
import { DiffId, diffById, loadSave, RunResult, SaveData, storeSave, Upgrade } from './game/config';
import { sound } from './game/audio';

type Screen = 'menu' | 'play' | 'pause' | 'upgrade' | 'over';

const EMPTY_HUD: HudState = { hp: 100, maxHp: 100, gold: 0, score: 0, floor: 1, kills: 0, spell: 2, spellMax: 2, dodge: 1, combo: 0, left: 0, boss: null };

const CSS = `
.mz-root { font-family: 'Palatino Linotype', 'Book Antiqua', Palatino, Georgia, serif; }
.mz-title { font-family: 'Trajan Pro', 'Cinzel', 'Palatino Linotype', Georgia, serif; letter-spacing: .18em; text-shadow: 0 0 24px rgba(255,140,40,.55), 0 0 2px #000, 0 4px 0 #2a0f05; }
.mz-vignette { pointer-events: none; background: radial-gradient(ellipse at center, transparent 45%, rgba(4,2,8,.55) 80%, rgba(0,0,0,.9) 100%); }
.mz-hurt { pointer-events: none; animation: mzHurt .45s ease-out forwards; background: radial-gradient(ellipse at center, transparent 40%, rgba(200,10,30,.55) 100%); }
@keyframes mzHurt { from { opacity: 1 } to { opacity: 0 } }
.mz-toast { animation: mzToast 1.8s ease-out forwards; }
@keyframes mzToast { 0% { opacity: 0; transform: translateY(10px) scale(.9) } 12% { opacity: 1; transform: none } 80% { opacity: 1 } 100% { opacity: 0; transform: translateY(-14px) } }
.mz-panel { background: linear-gradient(180deg, rgba(28,18,24,.92), rgba(12,8,14,.95)); border: 1px solid rgba(214,160,80,.35); box-shadow: 0 0 0 1px rgba(0,0,0,.6), 0 20px 60px rgba(0,0,0,.6), inset 0 1px 0 rgba(255,220,160,.08); }
.mz-btn { background: linear-gradient(180deg, #e0902e, #a4521a); border: 1px solid #ffc06a; color: #1a0a04; text-shadow: 0 1px 0 rgba(255,220,170,.5); box-shadow: 0 0 24px rgba(255,130,40,.35), inset 0 1px 0 rgba(255,240,200,.5); }
.mz-btn:hover { filter: brightness(1.12); }
.mz-ember { animation: mzEmber 2.4s ease-in-out infinite; }
@keyframes mzEmber { 0%,100% { opacity: .75 } 50% { opacity: 1 } }
.mz-fadein { animation: mzFade .5s ease-out; }
@keyframes mzFade { from { opacity: 0; transform: translateY(12px) } to { opacity: 1; transform: none } }
`;

export default function App() {
  const hostRef = useRef<HTMLDivElement>(null), gameRef = useRef<Game | null>(null);
  const [screen, setScreen] = useState<Screen>('menu'), screenRef = useRef<Screen>('menu');
  const [hud, setHud] = useState<HudState>(EMPTY_HUD);
  const [save, setSave] = useState<SaveData>(() => loadSave()), saveRef = useRef(save);
  const [result, setResult] = useState<{ r: RunResult; record: boolean } | null>(null);
  const [choices, setChoices] = useState<Upgrade[]>([]);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [hurtKey, setHurtKey] = useState(0);
  const [muted, setMuted] = useState(false);
  const [touch] = useState(() => typeof window !== 'undefined' && (window.matchMedia?.('(pointer: coarse)').matches ?? false));
  const timers = useRef<number[]>([]), toastId = useRef(0);

  const go = (s: Screen) => { screenRef.current = s; setScreen(s); };
  const persist = (s: SaveData) => { saveRef.current = s; setSave(s); storeSave(s); };

  useEffect(() => {
    const host = hostRef.current; if (!host) return;
    const game = new Game(host, {
      onHud: h => setHud(h),
      onToast: (text, color) => {
        const id = ++toastId.current;
        setToasts(t => [...t.slice(-2), { id, text, color }]);
        timers.current.push(window.setTimeout(() => setToasts(t => t.filter(x => x.id !== id)), 1800));
      },
      onUpgrade: c => { setChoices(c); go('upgrade'); },
      onHurt: () => setHurtKey(k => k + 1),
      onOver: r => {
        const prev = saveRef.current, record = r.score > prev.best;
        persist({ ...prev, best: Math.max(prev.best, r.score), bestFloor: Math.max(prev.bestFloor, r.floor), runs: prev.runs + 1 });
        setResult({ r, record }); go('over');
        if (record) { try { confetti({ particleCount: 140, spread: 90, origin: { y: 0.3 }, colors: ['#ffb45a', '#ff6a2a', '#ffe0a0', '#7ac8ff'] }); } catch { /* sin confeti */ } }
      },
    });
    game.toAttract();
    gameRef.current = game;
    return () => {
      timers.current.forEach(t => window.clearTimeout(t)); timers.current = [];
      game.dispose(); gameRef.current = null; sound.dispose();
    };
  }, []);

  const start = useCallback(() => {
    const g = gameRef.current; if (!g) return;
    sound.init(); sound.setMuted(muted);
    (document.activeElement as HTMLElement | null)?.blur?.();
    setToasts([]); setResult(null); setHud(EMPTY_HUD);
    g.newRun(diffById(saveRef.current.diff));
    go('play');
  }, [muted]);

  const toMenu = useCallback(() => { gameRef.current?.toAttract(); setToasts([]); go('menu'); }, []);

  const setPaused = useCallback((p: boolean) => {
    const g = gameRef.current; if (!g) return;
    g.setPaused(p); go(p ? 'pause' : 'play');
  }, []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.code !== 'Escape' && e.code !== 'KeyP') return;
      if (screenRef.current === 'play') setPaused(true); else if (screenRef.current === 'pause') setPaused(false);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [setPaused]);

  const toggleMute = () => { sound.init(); sound.setMuted(!muted); setMuted(!muted); };
  const pickUpgrade = (u: Upgrade) => { gameRef.current?.chooseUpgrade(u); go('play'); };
  const setDiff = (id: DiffId) => { sound.click(); persist({ ...saveRef.current, diff: id }); };

  return (
    <div className="mz-root relative h-screen min-h-[420px] w-full select-none overflow-hidden bg-[#06050a] text-amber-50">
      <style>{CSS}</style>
      <div ref={hostRef} className="absolute inset-0" />
      <div className="mz-vignette absolute inset-0" />
      {hurtKey > 0 && <div key={hurtKey} className="mz-hurt absolute inset-0" />}

      {screen === 'menu' && <Menu save={save} muted={muted} onMute={toggleMute} onPlay={start} onDiff={setDiff} />}

      {(screen === 'play' || screen === 'pause' || screen === 'upgrade') && gameRef.current && (
        <Hud hud={hud} toasts={toasts} muted={muted} touch={touch} pad={gameRef.current.input.virtual}
          onPause={() => setPaused(true)} onMute={toggleMute} />
      )}

      {screen === 'pause' && <PauseMenu onResume={() => setPaused(false)} onRestart={start} onMenu={toMenu} />}
      {screen === 'upgrade' && <UpgradePick choices={choices} onPick={pickUpgrade} />}
      {screen === 'over' && result && (
        <GameOver r={result.r} record={result.record} best={save.best} bestFloor={save.bestFloor} onRetry={start} onMenu={toMenu} />
      )}
    </div>
  );
}

import { useRef } from 'react';
import { Coins, Heart, Pause, Skull, Sparkles, Sword, Volume2, VolumeX, Wind, Zap } from 'lucide-react';
import clsx from 'clsx';
import { HudState } from '../game/engine';
import { VirtualPad } from '../game/input';

export interface Toast { id: number; text: string; color: string }

interface Props {
  hud: HudState; toasts: Toast[]; muted: boolean; touch: boolean; pad: VirtualPad;
  onPause: () => void; onMute: () => void;
}

function Joystick({ pad }: { pad: VirtualPad }) {
  const base = useRef<HTMLDivElement>(null), knob = useRef<HTMLDivElement>(null), id = useRef<number | null>(null);
  const move = (e: React.PointerEvent) => {
    if (id.current !== e.pointerId || !base.current || !knob.current) return;
    const r = base.current.getBoundingClientRect(), R = r.width / 2;
    let dx = e.clientX - (r.left + R), dy = e.clientY - (r.top + R);
    const l = Math.hypot(dx, dy); if (l > R) { dx *= R / l; dy *= R / l; }
    pad.x = dx / R; pad.y = -dy / R;
    knob.current.style.transform = `translate(${dx}px, ${dy}px)`;
  };
  const end = () => { id.current = null; pad.x = 0; pad.y = 0; if (knob.current) knob.current.style.transform = ''; };
  return (
    <div ref={base} className="pointer-events-auto relative h-32 w-32 touch-none rounded-full border border-amber-200/25 bg-black/35 backdrop-blur-sm"
      onPointerDown={e => { id.current = e.pointerId; (e.target as HTMLElement).setPointerCapture(e.pointerId); move(e); }}
      onPointerMove={move} onPointerUp={end} onPointerCancel={end}>
      <div ref={knob} className="absolute left-1/2 top-1/2 -ml-7 -mt-7 h-14 w-14 rounded-full border border-amber-200/50 bg-amber-500/40 shadow-[0_0_20px_rgba(255,150,60,.4)]" />
    </div>
  );
}

function PadButton({ label, onSet, className, children }: { label: string; onSet: (v: boolean) => void; className?: string; children: React.ReactNode }) {
  return (
    <button aria-label={label}
      className={clsx('pointer-events-auto flex touch-none flex-col items-center justify-center rounded-full border text-[10px] font-bold uppercase tracking-wider backdrop-blur-sm active:scale-95', className)}
      onPointerDown={e => { e.preventDefault(); onSet(true); }} onPointerUp={() => onSet(false)} onPointerLeave={() => onSet(false)} onPointerCancel={() => onSet(false)}>
      {children}<span className="mt-0.5">{label}</span>
    </button>
  );
}

export default function Hud({ hud, toasts, muted, touch, pad, onPause, onMute }: Props) {
  const hpPct = Math.max(0, Math.min(1, hud.hp / hud.maxHp));
  const low = hpPct < 0.3;
  return (
    <div className="pointer-events-none absolute inset-0 text-amber-50">
      {/* Vida, oro y piso */}
      <div className="absolute left-3 top-3 w-[min(320px,60vw)] sm:left-5 sm:top-5">
        <div className="flex items-center gap-2">
          <Heart className={clsx('h-6 w-6 shrink-0 fill-red-600 text-red-400 drop-shadow-[0_0_8px_rgba(255,40,60,.7)]', low && 'animate-pulse')} />
          <div className="relative h-5 flex-1 overflow-hidden rounded-sm border border-amber-200/30 bg-black/70 shadow-[0_0_14px_rgba(0,0,0,.8)]">
            <div className="absolute inset-y-0 left-0 bg-gradient-to-r from-red-900 via-red-600 to-rose-400 transition-all duration-200" style={{ width: `${hpPct * 100}%` }} />
            <div className="absolute inset-x-0 top-0 h-1/2 bg-white/10" />
            <span className="absolute inset-0 flex items-center justify-center text-xs font-bold tracking-wider text-white drop-shadow">{hud.hp} / {hud.maxHp}</span>
          </div>
        </div>
        <div className="mt-2 flex items-center gap-4 pl-8 text-sm">
          <span className="flex items-center gap-1 font-bold text-amber-300"><Coins className="h-4 w-4" />{hud.gold}</span>
          <span className="flex items-center gap-1 text-violet-300">
            <Sparkles className="h-4 w-4" />
            {Array.from({ length: hud.spellMax }, (_, i) => (
              <span key={i} className={clsx('inline-block h-2.5 w-2.5 rotate-45 border border-violet-300/70', i < hud.spell ? 'bg-violet-400 shadow-[0_0_8px_rgba(170,130,255,.9)]' : 'bg-black/50')} />
            ))}
          </span>
          <span className="flex items-center gap-1 text-sky-200">
            <Wind className="h-4 w-4" />
            <span className="h-1.5 w-10 overflow-hidden rounded bg-black/60"><span className="block h-full bg-sky-300" style={{ width: `${Math.max(0, Math.min(1, hud.dodge)) * 100}%` }} /></span>
          </span>
        </div>
      </div>

      {/* Puntuación y menú */}
      <div className="absolute right-3 top-3 flex items-start gap-2 sm:right-5 sm:top-5">
        <div className="text-right">
          <div className="text-[10px] uppercase tracking-[0.3em] text-amber-200/60">Piso {hud.floor}</div>
          <div className="text-2xl font-bold tabular-nums text-amber-100 drop-shadow-[0_0_10px_rgba(255,150,60,.5)]">{hud.score.toLocaleString('es-ES')}</div>
          <div className="flex items-center justify-end gap-1 text-xs text-stone-300"><Skull className="h-3.5 w-3.5" />{hud.kills} · quedan {hud.left}</div>
          {hud.combo >= 2 && <div className="mt-1 flex items-center justify-end gap-1 text-sm font-bold text-orange-300"><Zap className="h-4 w-4" />Combo x{hud.combo}</div>}
        </div>
        <button onClick={onMute} className="pointer-events-auto rounded-md border border-amber-200/20 bg-black/50 p-2 hover:bg-black/70" aria-label="Sonido">
          {muted ? <VolumeX className="h-4 w-4" /> : <Volume2 className="h-4 w-4" />}
        </button>
        <button onClick={onPause} className="pointer-events-auto rounded-md border border-amber-200/20 bg-black/50 p-2 hover:bg-black/70" aria-label="Pausa">
          <Pause className="h-4 w-4" />
        </button>
      </div>

      {/* Jefe */}
      {hud.boss && (
        <div className="absolute left-1/2 top-16 w-[min(560px,80vw)] -translate-x-1/2 text-center sm:top-6">
          <div className="mz-title mb-1 text-sm uppercase text-cyan-200">{hud.boss.name}</div>
          <div className="h-3 overflow-hidden rounded-sm border border-cyan-200/40 bg-black/70">
            <div className="h-full bg-gradient-to-r from-cyan-700 via-cyan-400 to-sky-200 shadow-[0_0_12px_rgba(80,220,255,.8)] transition-all" style={{ width: `${(hud.boss.hp / hud.boss.max) * 100}%` }} />
          </div>
        </div>
      )}

      {/* Avisos */}
      <div className="absolute left-1/2 top-[26%] flex -translate-x-1/2 flex-col items-center gap-1">
        {toasts.map(t => (
          <div key={t.id} className="mz-toast mz-title whitespace-nowrap text-xl font-bold sm:text-2xl" style={{ color: t.color }}>{t.text}</div>
        ))}
      </div>

      {!touch && (
        <div className="absolute bottom-3 left-1/2 -translate-x-1/2 rounded-full border border-amber-200/10 bg-black/40 px-4 py-1 text-[11px] text-amber-100/60">
          WASD / flechas mover · Espacio atacar · Shift esquivar · E hechizo · Esc pausa
        </div>
      )}

      {touch && (
        <>
          <div className="absolute bottom-6 left-6"><Joystick pad={pad} /></div>
          <div className="absolute bottom-6 right-6 grid grid-cols-2 items-end gap-3">
            <PadButton label="Hechizo" onSet={v => { pad.spell = v; }} className="h-16 w-16 border-violet-300/50 bg-violet-700/40"><Sparkles className="h-5 w-5" /></PadButton>
            <PadButton label="Atacar" onSet={v => { pad.attack = v; }} className="row-span-2 h-24 w-24 border-amber-200/60 bg-amber-600/45"><Sword className="h-8 w-8" /></PadButton>
            <PadButton label="Esquivar" onSet={v => { pad.dodge = v; }} className="h-16 w-16 border-sky-300/50 bg-sky-700/40"><Wind className="h-5 w-5" /></PadButton>
          </div>
        </>
      )}
    </div>
  );
}

import { Coins, Crosshair, Droplet, Flame, Footprints, Heart, Home, Magnet, Play, RotateCcw, Skull, Sparkles, Sword, Trophy, Volume2, VolumeX, Wind } from 'lucide-react';
import clsx from 'clsx';
import { DiffId, DIFFS, RunResult, SaveData, Upgrade } from '../game/config';

const ICONS: Record<string, typeof Heart> = { Heart, Sword, Footprints, Flame, Droplet, Crosshair, Wind, Sparkles, Magnet };

const fmtTime = (s: number) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;

export function Menu({ save, muted, onMute, onPlay, onDiff }: {
  save: SaveData; muted: boolean; onMute: () => void; onPlay: () => void; onDiff: (d: DiffId) => void;
}) {
  return (
    <div className="absolute inset-0 overflow-y-auto bg-gradient-to-r from-black/85 via-black/45 to-transparent">
      <div className="mz-fadein flex min-h-full max-w-xl flex-col justify-center gap-5 px-6 py-8 sm:px-12">
        <div>
          <div className="mz-ember text-xs uppercase tracking-[0.5em] text-amber-400/80">Roguelike de antorchas</div>
          <h1 className="mz-title mt-1 text-5xl font-bold uppercase text-amber-100 sm:text-7xl">Mazmorra</h1>
          <p className="mt-3 max-w-md text-base leading-relaxed text-amber-50/75">
            Desciende piso a piso por criptas que cambian en cada partida. Esquiva, golpea, saquea cofres
            de bendiciones y enfréntate al Rey Liche que aguarda cada tres niveles.
          </p>
        </div>

        <div>
          <div className="mb-2 text-[11px] uppercase tracking-[0.3em] text-amber-200/60">Dificultad</div>
          <div className="grid grid-cols-3 gap-2">
            {DIFFS.map(d => (
              <button key={d.id} onClick={() => onDiff(d.id)}
                className={clsx('rounded-md border px-3 py-2 text-left transition',
                  save.diff === d.id ? 'border-amber-300/80 bg-amber-500/20 shadow-[0_0_18px_rgba(255,160,60,.25)]' : 'border-amber-100/10 bg-black/40 hover:border-amber-200/40')}>
                <div className={clsx('text-sm font-bold', d.id === 'pesadilla' ? 'text-red-300' : 'text-amber-100')}>{d.name}</div>
                <div className="text-[11px] leading-tight text-amber-50/55">{d.desc}</div>
              </button>
            ))}
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-3">
          <button onClick={onPlay} className="mz-btn flex items-center gap-2 rounded-md px-10 py-3 text-lg font-bold uppercase tracking-[0.2em]">
            <Play className="h-5 w-5 fill-current" />Jugar
          </button>
          <button onClick={onMute} className="rounded-md border border-amber-200/20 bg-black/50 p-3 text-amber-100 hover:bg-black/70" aria-label="Sonido">
            {muted ? <VolumeX className="h-5 w-5" /> : <Volume2 className="h-5 w-5" />}
          </button>
          <div className="flex items-center gap-2 rounded-md border border-amber-200/15 bg-black/40 px-3 py-2 text-sm">
            <Trophy className="h-4 w-4 text-amber-300" />
            <span className="text-amber-50/70">Récord</span>
            <span className="font-bold tabular-nums text-amber-200">{save.best.toLocaleString('es-ES')}</span>
            <span className="text-amber-50/40">· piso {save.bestFloor}</span>
          </div>
        </div>

        <div className="grid grid-cols-2 gap-x-6 gap-y-1 text-xs text-amber-50/60 sm:max-w-md">
          <span><b className="text-amber-200/90">WASD / Flechas</b> moverse</span>
          <span><b className="text-amber-200/90">Espacio / J</b> atacar</span>
          <span><b className="text-amber-200/90">Shift / K</b> esquivar</span>
          <span><b className="text-amber-200/90">E / L</b> hechizo arcano</span>
          <span><b className="text-amber-200/90">Esc / P</b> pausa</span>
          <span><b className="text-amber-200/90">Móvil</b> joystick y botones</span>
        </div>
      </div>
    </div>
  );
}

function Overlay({ children }: { children: React.ReactNode }) {
  return <div className="absolute inset-0 flex items-center justify-center bg-black/60 p-4 backdrop-blur-[2px]">{children}</div>;
}

export function PauseMenu({ onResume, onRestart, onMenu }: { onResume: () => void; onRestart: () => void; onMenu: () => void }) {
  return (
    <Overlay>
      <div className="mz-panel mz-fadein w-full max-w-xs rounded-lg p-6 text-center">
        <h2 className="mz-title text-3xl uppercase text-amber-100">Pausa</h2>
        <div className="mt-5 flex flex-col gap-2">
          <button onClick={onResume} className="mz-btn flex items-center justify-center gap-2 rounded-md py-2.5 font-bold uppercase tracking-wider"><Play className="h-4 w-4" />Continuar</button>
          <button onClick={onRestart} className="flex items-center justify-center gap-2 rounded-md border border-amber-200/25 bg-black/40 py-2.5 hover:bg-black/60"><RotateCcw className="h-4 w-4" />Reiniciar</button>
          <button onClick={onMenu} className="flex items-center justify-center gap-2 rounded-md border border-amber-200/25 bg-black/40 py-2.5 hover:bg-black/60"><Home className="h-4 w-4" />Menú</button>
        </div>
      </div>
    </Overlay>
  );
}

export function UpgradePick({ choices, onPick }: { choices: Upgrade[]; onPick: (u: Upgrade) => void }) {
  return (
    <Overlay>
      <div className="mz-fadein w-full max-w-3xl text-center">
        <div className="text-xs uppercase tracking-[0.4em] text-amber-300/80">Cofre del tesoro</div>
        <h2 className="mz-title mt-1 text-3xl uppercase text-amber-100 sm:text-4xl">Elige una bendición</h2>
        <div className="mt-6 grid gap-3 sm:grid-cols-3">
          {choices.map(u => {
            const Icon = ICONS[u.icon] ?? Sparkles;
            return (
              <button key={u.id} onClick={() => onPick(u)}
                className="mz-panel group rounded-lg p-5 text-left transition hover:-translate-y-1 hover:border-amber-300/70">
                <div className="mb-3 flex h-12 w-12 items-center justify-center rounded-full border" style={{ borderColor: u.color, boxShadow: `0 0 22px ${u.color}66`, color: u.color }}>
                  <Icon className="h-6 w-6" />
                </div>
                <div className="text-lg font-bold text-amber-50">{u.name}</div>
                <div className="mt-1 text-sm text-amber-50/65">{u.desc}</div>
              </button>
            );
          })}
        </div>
      </div>
    </Overlay>
  );
}

export function GameOver({ r, record, best, bestFloor, onRetry, onMenu }: {
  r: RunResult; record: boolean; best: number; bestFloor: number; onRetry: () => void; onMenu: () => void;
}) {
  const rows: Array<[typeof Heart, string, string]> = [
    [Skull, 'Enemigos abatidos', String(r.kills)],
    [Coins, 'Oro reunido', String(r.gold)],
    [Flame, 'Piso alcanzado', String(r.floor)],
    [Footprints, 'Tiempo', fmtTime(r.time)],
  ];
  return (
    <Overlay>
      <div className="mz-panel mz-fadein w-full max-w-sm rounded-lg p-6 text-center">
        <div className="text-xs uppercase tracking-[0.4em] text-red-400/80">Has caído</div>
        <h2 className="mz-title mt-1 text-3xl uppercase text-amber-100">Fin de la partida</h2>
        <div className="mt-1 text-xs text-amber-50/50">Abatido por: {r.cause || 'la oscuridad'}</div>
        <div className="mt-4 text-4xl font-bold tabular-nums text-amber-200">{r.score.toLocaleString('es-ES')}</div>
        {record
          ? <div className="mt-1 flex items-center justify-center gap-1 text-sm font-bold text-amber-300"><Trophy className="h-4 w-4" />¡Nuevo récord!</div>
          : <div className="mt-1 text-xs text-amber-50/50">Récord: {best.toLocaleString('es-ES')} · piso {bestFloor}</div>}
        <div className="mt-4 grid grid-cols-2 gap-2 text-left text-sm">
          {rows.map(([I, k, v]) => (
            <div key={k} className="flex items-center gap-2 rounded border border-amber-100/10 bg-black/30 px-2 py-1.5">
              <I className="h-4 w-4 text-amber-300/80" /><span className="flex-1 text-amber-50/60">{k}</span><b>{v}</b>
            </div>
          ))}
        </div>
        <div className="mt-5 flex gap-2">
          <button onClick={onRetry} className="mz-btn flex flex-1 items-center justify-center gap-2 rounded-md py-2.5 font-bold uppercase tracking-wider"><RotateCcw className="h-4 w-4" />Reintentar</button>
          <button onClick={onMenu} className="flex items-center justify-center gap-2 rounded-md border border-amber-200/25 bg-black/40 px-4 py-2.5 hover:bg-black/60"><Home className="h-4 w-4" />Menú</button>
        </div>
      </div>
    </Overlay>
  );
}

// Audio procedural con Web Audio API: efectos con osciladores/ruido y un drone ambiental de cripta.
class Sound {
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  private musicGain: GainNode | null = null;
  private noiseBuf: AudioBuffer | null = null;
  private muted = false;
  private musicNodes: AudioScheduledSourceNode[] = [];
  private bellTimer = 0;

  init() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {}); return; }
    try {
      const AC = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.muted ? 0 : 0.55;
      this.master.connect(this.ctx.destination);
      const len = this.ctx.sampleRate;
      this.noiseBuf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
      const d = this.noiseBuf.getChannelData(0);
      for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
      this.startMusic();
    } catch { this.ctx = null; }
  }

  setMuted(m: boolean) {
    this.muted = m;
    if (this.master && this.ctx) this.master.gain.setTargetAtTime(m ? 0 : 0.55, this.ctx.currentTime, 0.05);
  }
  isMuted() { return this.muted; }

  private tone(freq: number, dur: number, type: OscillatorType, vol: number, slide = 0, delay = 0) {
    const c = this.ctx, m = this.master; if (!c || !m) return;
    const t = c.currentTime + delay;
    const o = c.createOscillator(), g = c.createGain();
    o.type = type; o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq * slide), t + dur);
    g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    o.connect(g); g.connect(m); o.start(t); o.stop(t + dur + 0.02);
  }

  private noise(dur: number, vol: number, freq: number, q = 1, type: BiquadFilterType = 'bandpass', delay = 0) {
    const c = this.ctx, m = this.master; if (!c || !m || !this.noiseBuf) return;
    const t = c.currentTime + delay;
    const s = c.createBufferSource(); s.buffer = this.noiseBuf;
    const f = c.createBiquadFilter(); f.type = type; f.frequency.value = freq; f.Q.value = q;
    const g = c.createGain(); g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    s.connect(f); f.connect(g); g.connect(m); s.start(t, Math.random() * 0.5); s.stop(t + dur + 0.02);
  }

  swing() { this.noise(0.16, 0.35, 1800, 0.8, 'bandpass'); this.tone(320, 0.1, 'triangle', 0.05, 0.5); }
  hit(crit = false) { this.noise(0.12, 0.5, 700, 1.2, 'lowpass'); this.tone(crit ? 220 : 160, 0.12, 'square', 0.12, 0.4); }
  hurt() { this.tone(180, 0.3, 'sawtooth', 0.22, 0.4); this.noise(0.2, 0.3, 400, 1, 'lowpass'); }
  dodge() { this.noise(0.25, 0.25, 900, 0.6, 'highpass'); }
  coin() { this.tone(1320, 0.08, 'square', 0.06); this.tone(1760, 0.14, 'square', 0.06, 1, 0.06); }
  potion() { [523, 659, 784].forEach((f, i) => this.tone(f, 0.2, 'sine', 0.14, 1, i * 0.06)); }
  chest() { [392, 494, 587, 784, 988].forEach((f, i) => this.tone(f, 0.35, 'triangle', 0.12, 1, i * 0.07)); }
  stairs() { [392, 330, 262, 196].forEach((f, i) => this.tone(f, 0.5, 'sine', 0.16, 1, i * 0.12)); }
  spell() { this.tone(880, 0.4, 'sawtooth', 0.08, 0.25); this.noise(0.35, 0.2, 2500, 2); }
  fireball() { this.noise(0.4, 0.18, 500, 0.7, 'lowpass'); this.tone(140, 0.3, 'triangle', 0.08, 0.6); }
  boom() { this.noise(0.6, 0.6, 200, 0.7, 'lowpass'); this.tone(70, 0.5, 'sine', 0.35, 0.4); }
  die() { this.tone(260, 0.35, 'square', 0.08, 0.3); this.noise(0.3, 0.25, 1200, 1.5); }
  roar() { this.tone(90, 1.2, 'sawtooth', 0.25, 0.5); this.tone(60, 1.4, 'square', 0.15, 0.6); this.noise(1.0, 0.3, 300, 0.5, 'lowpass'); }
  vase() { this.noise(0.18, 0.4, 3000, 1.2); this.tone(1100, 0.06, 'triangle', 0.05, 0.7); }
  click() { this.tone(660, 0.05, 'square', 0.06); }
  levelUp() { [523, 659, 784, 1047].forEach((f, i) => this.tone(f, 0.3, 'triangle', 0.13, 1, i * 0.08)); }

  private startMusic() {
    const c = this.ctx, m = this.master; if (!c || !m) return;
    this.musicGain = c.createGain(); this.musicGain.gain.value = 0.11;
    const filt = c.createBiquadFilter(); filt.type = 'lowpass'; filt.frequency.value = 420; filt.Q.value = 4;
    const lfo = c.createOscillator(), lg = c.createGain();
    lfo.frequency.value = 0.07; lg.gain.value = 260; lfo.connect(lg); lg.connect(filt.frequency);
    filt.connect(this.musicGain); this.musicGain.connect(m);
    for (const f of [55, 82.4, 110.6]) {
      const o = c.createOscillator(); o.type = 'sawtooth'; o.frequency.value = f; o.detune.value = Math.random() * 10 - 5;
      o.connect(filt); o.start(); this.musicNodes.push(o);
    }
    lfo.start(); this.musicNodes.push(lfo);
    // campana lejana ocasional
    const notes = [220, 261.6, 293.7, 329.6, 196];
    this.bellTimer = window.setInterval(() => {
      if (!this.ctx || this.muted) return;
      const f = notes[Math.floor(Math.random() * notes.length)];
      this.tone(f, 2.4, 'sine', 0.05); this.tone(f * 2.01, 1.6, 'sine', 0.02);
    }, 4200);
  }

  dispose() {
    window.clearInterval(this.bellTimer);
    this.musicNodes.forEach(n => { try { n.stop(); } catch { /* ya parado */ } });
    this.musicNodes = [];
    this.ctx?.close().catch(() => {});
    this.ctx = null; this.master = null;
  }
}

