// Generación procedural de pisos (salas conectadas por pasillos) y su construcción 3D con antorchas.
import * as THREE from 'three';
import { Rng } from './config';
import { canvasTexture, lin, litMat, radialTexture } from './three-compat';

export const TILE = 2;
export const WALL = 0, FLOOR = 1, PILLAR = 2, PROP = 3;
export type RoomKind = 'start' | 'normal' | 'treasure' | 'stairs';
export interface Room { id: number; x: number; y: number; w: number; h: number; kind: RoomKind; depth: number; cx: number; cz: number }
export interface Torch { pos: THREE.Vector3; glow: THREE.Sprite; flame: THREE.Sprite; phase: number; range: number }

export interface DungeonTextures { floor: THREE.Texture; wall: THREE.Texture; banner: THREE.Texture; glow: THREE.Texture; flame: THREE.Texture; rune: THREE.Texture }

export function makeDungeonTextures(): DungeonTextures {
  const floor = canvasTexture(256, 256, g => {
    g.fillStyle = '#8a8590'; g.fillRect(0, 0, 256, 256);
    const slabs: Array<[number, number, number, number]> = [[0, 0, 128, 128], [128, 0, 128, 80], [128, 80, 128, 48], [0, 128, 80, 128], [80, 128, 176, 128]];
    for (const [x, y, w, h] of slabs) {
      const v = 120 + Math.random() * 40;
      g.fillStyle = `rgb(${v},${v - 6},${v + 6})`; g.fillRect(x + 3, y + 3, w - 6, h - 6);
      for (let i = 0; i < 160; i++) {
        const c = Math.random() * 50 + v - 30;
        g.fillStyle = `rgba(${c},${c},${c + 8},0.5)`; g.fillRect(x + 3 + Math.random() * (w - 8), y + 3 + Math.random() * (h - 8), 2 + Math.random() * 3, 2 + Math.random() * 3);
      }
      g.strokeStyle = 'rgba(40,36,48,0.6)'; g.lineWidth = 1.5;
      g.beginPath(); g.moveTo(x + 10 + Math.random() * 30, y + 6); g.lineTo(x + 20 + Math.random() * 40, y + h * 0.6); g.stroke();
    }
    g.strokeStyle = '#2a2530'; g.lineWidth = 5;
    for (const [x, y, w, h] of slabs) g.strokeRect(x, y, w, h);
  }, false);
  const wall = canvasTexture(256, 256, g => {
    g.fillStyle = '#2c2832'; g.fillRect(0, 0, 256, 256);
    const rows = 6, bh = 256 / rows;
    for (let r = 0; r < rows; r++) {
      const off = r % 2 ? 0 : 42;
      for (let x = -84 + off; x < 256; x += 84) {
        const v = 105 + Math.random() * 45;
        g.fillStyle = `rgb(${v},${v - 8},${v + 4})`;
        g.fillRect(x + 3, r * bh + 3, 78, bh - 6);
        g.fillStyle = 'rgba(255,255,255,0.08)'; g.fillRect(x + 3, r * bh + 3, 78, 4);
        g.fillStyle = 'rgba(0,0,0,0.18)'; g.fillRect(x + 3, r * bh + bh - 9, 78, 6);
        if (Math.random() < 0.25) { g.fillStyle = 'rgba(60,90,50,0.35)'; g.fillRect(x + 3, r * bh + 3, 30 + Math.random() * 40, bh - 6); }
      }
    }
  }, false);
  const banner = canvasTexture(64, 128, g => {
    const gr = g.createLinearGradient(0, 0, 0, 128); gr.addColorStop(0, '#7a0f1a'); gr.addColorStop(1, '#3a0610');
    g.fillStyle = gr; g.fillRect(0, 0, 64, 128);
    g.fillStyle = '#d4a23a'; g.fillRect(0, 0, 64, 6); g.fillRect(4, 10, 3, 104); g.fillRect(57, 10, 3, 104);
    g.beginPath(); g.moveTo(32, 30); g.lineTo(46, 52); g.lineTo(32, 86); g.lineTo(18, 52); g.closePath(); g.fill();
    g.fillStyle = '#7a0f1a'; g.beginPath(); g.arc(32, 54, 7, 0, Math.PI * 2); g.fill();
    g.clearRect(0, 116, 64, 12); g.fillStyle = '#3a0610';
    g.beginPath(); g.moveTo(0, 116); g.lineTo(32, 128); g.lineTo(64, 116); g.fill();
  }, false);
  const glow = radialTexture([[0, 'rgba(255,200,120,1)'], [0.25, 'rgba(255,130,40,0.55)'], [1, 'rgba(255,60,0,0)']], 128);
  const flame = radialTexture([[0, 'rgba(255,255,220,1)'], [0.35, 'rgba(255,190,60,0.9)'], [1, 'rgba(255,80,0,0)']], 64);
  const rune = canvasTexture(128, 128, g => {
    g.translate(64, 64); g.strokeStyle = 'rgba(140,200,255,1)'; g.lineWidth = 4;
    g.beginPath(); g.arc(0, 0, 58, 0, Math.PI * 2); g.stroke();
    g.lineWidth = 2; g.beginPath(); g.arc(0, 0, 46, 0, Math.PI * 2); g.stroke();
    for (let i = 0; i < 12; i++) { g.rotate(Math.PI / 6); g.fillStyle = 'rgba(160,220,255,1)'; g.fillRect(-2, -56, 4, 8); }
    g.beginPath(); for (let i = 0; i < 6; i++) { const a = i * Math.PI / 3; g.lineTo(Math.cos(a) * 40, Math.sin(a) * 40); } g.closePath(); g.stroke();
  });
  return { floor, wall, banner, glow, flame, rune };
}

export class Dungeon {
  W: number; H: number;
  grid: Uint8Array; roomOf: Int8Array; flow: Int16Array;
  rooms: Room[] = [];
  start!: Room; stairsRoom!: Room;
  group = new THREE.Group();
  torches: Torch[] = [];
  private disposables: Array<{ dispose: () => void }> = [];

  constructor(public floorN: number, private rng: Rng, private tex: DungeonTextures) {
    const cols = floorN >= 4 ? 4 : 3, rows = 3, SL = 13;
    this.W = cols * SL + 2; this.H = rows * SL + 2;
    this.grid = new Uint8Array(this.W * this.H);
    this.roomOf = new Int8Array(this.W * this.H).fill(-1);
    this.flow = new Int16Array(this.W * this.H).fill(-1);
    this.generate(cols, rows, SL);
    this.build();
  }

  idx(i: number, j: number) { return j * this.W + i; }
  cell(i: number, j: number) { return i < 0 || j < 0 || i >= this.W || j >= this.H ? WALL : this.grid[this.idx(i, j)]; }
  tile(v: number) { return Math.round(v / TILE); }
  walkableTile(i: number, j: number) { return this.cell(i, j) === FLOOR; }
  walkable(x: number, z: number) { return this.walkableTile(this.tile(x), this.tile(z)); }
  roomAt(x: number, z: number) { const i = this.tile(x), j = this.tile(z); return i < 0 || j < 0 || i >= this.W || j >= this.H ? -1 : this.roomOf[this.idx(i, j)]; }

  private generate(cols: number, rows: number, SL: number) {
    const r = this.rng;
    const carve = (i: number, j: number) => { if (i > 0 && j > 0 && i < this.W - 1 && j < this.H - 1) this.grid[this.idx(i, j)] = FLOOR; };
    for (let sy = 0; sy < rows; sy++) for (let sx = 0; sx < cols; sx++) {
      const first = sx === 0 && sy === 0;
      const w = first ? 8 : 6 + Math.floor(r() * 5), h = first ? 8 : 6 + Math.floor(r() * 5);
      const x = 2 + sx * SL + Math.floor(r() * (SL - 2 - w)), y = 2 + sy * SL + Math.floor(r() * (SL - 2 - h));
      const id = this.rooms.length;
      this.rooms.push({ id, x, y, w, h, kind: 'normal', depth: -1, cx: (x + (w - 1) / 2) * TILE, cz: (y + (h - 1) / 2) * TILE });
      for (let j = y; j < y + h; j++) for (let i = x; i < x + w; i++) { carve(i, j); this.roomOf[this.idx(i, j)] = id; }
    }
    // Árbol de expansión aleatorio sobre la rejilla de salas + conexiones extra (bucles)
    const adj: number[][] = this.rooms.map(() => []);
    const link = (a: number, b: number) => { if (adj[a].includes(b)) return; adj[a].push(b); adj[b].push(a); this.corridor(this.rooms[a], this.rooms[b], carve); };
    const seen = new Set<number>([0]), stack = [0];
    while (stack.length) {
      const c = stack[stack.length - 1], cx = c % cols, cy = Math.floor(c / cols);
      const nb = [[1, 0], [-1, 0], [0, 1], [0, -1]].map(([dx, dy]) => [cx + dx, cy + dy])
        .filter(([x, y]) => x >= 0 && y >= 0 && x < cols && y < rows && !seen.has(y * cols + x));
      if (!nb.length) { stack.pop(); continue; }
      const [nx, ny] = nb[Math.floor(r() * nb.length)], n = ny * cols + nx;
      seen.add(n); stack.push(n); link(c, n);
    }
    for (let k = 0; k < 2; k++) {
      const a = Math.floor(r() * this.rooms.length), ax = a % cols, ay = Math.floor(a / cols);
      if (ax + 1 < cols) link(a, a + 1); else if (ay + 1 < rows) link(a, a + cols);
    }
    // Profundidad (BFS) → la sala más lejana tiene la escalera
    this.rooms[0].depth = 0; const q = [0];
    while (q.length) { const c = q.shift()!; for (const n of adj[c]) if (this.rooms[n].depth < 0) { this.rooms[n].depth = this.rooms[c].depth + 1; q.push(n); } }
    this.start = this.rooms[0]; this.start.kind = 'start';
    this.stairsRoom = this.rooms.reduce((a, b) => (b.depth > a.depth ? b : a)); this.stairsRoom.kind = 'stairs';
    const others = this.rooms.filter(x => x.kind === 'normal');
    for (let k = 0; k < (this.rooms.length > 9 ? 2 : 1) && others.length; k++) others.splice(Math.floor(r() * others.length), 1)[0].kind = 'treasure';
    // Columnas y barriles (bloquean el paso, nunca en la línea de los pasillos)
    for (const rm of this.rooms) {
      if (rm.w >= 9 && rm.h >= 9 && rm.kind !== 'start') for (const [i, j] of [[rm.x + 2, rm.y + 2], [rm.x + rm.w - 3, rm.y + 2], [rm.x + 2, rm.y + rm.h - 3], [rm.x + rm.w - 3, rm.y + rm.h - 3]]) this.grid[this.idx(i, j)] = PILLAR;
      for (const [i, j] of [[rm.x, rm.y], [rm.x + rm.w - 1, rm.y], [rm.x, rm.y + rm.h - 1]]) if (r() < 0.55 && this.isEnclosedCorner(i, j)) this.grid[this.idx(i, j)] = PROP;
    }
  }

  private isEnclosedCorner(i: number, j: number) {
    let walls = 0;
    for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) if (this.cell(i + dx, j + dy) === WALL) walls++;
    return walls >= 2;
  }

  private corridor(a: Room, b: Room, carve: (i: number, j: number) => void) {
    const ax = Math.round(a.cx / TILE), ay = Math.round(a.cz / TILE), bx = Math.round(b.cx / TILE), by = Math.round(b.cz / TILE);
    for (let i = Math.min(ax, bx); i <= Math.max(ax, bx); i++) { carve(i, ay); carve(i, ay + 1); }
    for (let j = Math.min(ay, by); j <= Math.max(ay, by) + 1; j++) { carve(bx, j); carve(bx + 1, j); }
  }

  randomSpot(room: Room, margin = 1, avoid?: { x: number; z: number }, minD = 0) {
    for (let k = 0; k < 40; k++) {
      const i = room.x + margin + Math.floor(this.rng() * Math.max(1, room.w - margin * 2));
      const j = room.y + margin + Math.floor(this.rng() * Math.max(1, room.h - margin * 2));
      if (!this.walkableTile(i, j)) continue;
      const x = i * TILE, z = j * TILE;
      if (avoid && Math.hypot(x - avoid.x, z - avoid.z) < minD) continue;
      return { x, z };
    }
    return { x: room.cx, z: room.cz };
  }

  /** Empuja un círculo fuera de las celdas bloqueadas. */
  collide(p: THREE.Vector3, rad: number) {
    for (let it = 0; it < 2; it++) {
      const ci = this.tile(p.x), cj = this.tile(p.z);
      for (let j = cj - 1; j <= cj + 1; j++) for (let i = ci - 1; i <= ci + 1; i++) {
        if (this.walkableTile(i, j)) continue;
        const h = this.cell(i, j) === PILLAR ? 0.6 : TILE / 2;
        const nx = Math.max(i * TILE - h, Math.min(p.x, i * TILE + h)), nz = Math.max(j * TILE - h, Math.min(p.z, j * TILE + h));
        const dx = p.x - nx, dz = p.z - nz, d2 = dx * dx + dz * dz;
        if (d2 < rad * rad) {
          if (d2 < 1e-6) { p.x += (p.x > i * TILE ? 1 : -1) * 0.05; continue; }
          const d = Math.sqrt(d2), push = rad - d;
          p.x += (dx / d) * push; p.z += (dz / d) * push;
        }
      }
    }
  }

  los(ax: number, az: number, bx: number, bz: number) {
    const d = Math.hypot(bx - ax, bz - az), n = Math.ceil(d / 0.6);
    for (let k = 1; k < n; k++) { const t = k / n; if (!this.walkable(ax + (bx - ax) * t, az + (bz - az) * t)) return false; }
    return true;
  }

  /** Campo de flujo (BFS) desde el jugador: los enemigos lo siguen por pasillos. */
  updateFlow(x: number, z: number) {
    const f = this.flow; f.fill(-1);
    const si = this.tile(x), sj = this.tile(z);
    if (!this.walkableTile(si, sj)) return;
    const q = new Int32Array(this.W * this.H); let h = 0, t = 0;
    q[t++] = this.idx(si, sj); f[q[0]] = 0;
    while (h < t) {
      const c = q[h++], i = c % this.W, j = (c - i) / this.W, d = f[c];
      if (d > 40) continue;
      for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const ni = i + dx, nj = j + dy, n = this.idx(ni, nj);
        if (this.walkableTile(ni, nj) && f[n] < 0) { f[n] = d + 1; q[t++] = n; }
      }
    }
  }
  flowDist(x: number, z: number) { const i = this.tile(x), j = this.tile(z); return this.walkableTile(i, j) ? this.flow[this.idx(i, j)] : -1; }
  flowDir(x: number, z: number, out: THREE.Vector3) {
    const i = this.tile(x), j = this.tile(z);
    let best = this.walkableTile(i, j) ? this.flow[this.idx(i, j)] : 9999, bi = i, bj = j;
    if (best < 0) best = 9999;
    for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
      if (!dx && !dy) continue;
      const ni = i + dx, nj = j + dy;
      if (!this.walkableTile(ni, nj) || (dx && dy && (!this.walkableTile(i + dx, j) || !this.walkableTile(i, j + dy)))) continue;
      const v = this.flow[this.idx(ni, nj)];
      if (v >= 0 && v < best) { best = v; bi = ni; bj = nj; }
    }
    out.set(bi * TILE - x, 0, bj * TILE - z);
    const l = out.length(); if (l > 1e-4) out.multiplyScalar(1 / l);
    return l > 1e-4;
  }

  // ---------------- Construcción 3D ----------------
  private track<T extends { dispose: () => void }>(o: T) { this.disposables.push(o); return o; }

  private instanced(geo: THREE.BufferGeometry, mat: THREE.Material, mats: THREE.Matrix4[], tints?: number[]) {
    if (!mats.length) return;
    if (tints) geo.setAttribute('aTint', new THREE.InstancedBufferAttribute(new Float32Array(tints), 3));
    const m = new THREE.InstancedMesh(this.track(geo), this.track(mat), mats.length);
    mats.forEach((mm, k) => m.setMatrixAt(k, mm));
    m.frustumCulled = false;
    this.group.add(m);
  }

  private build() {
    const r = this.rng, T = TILE, tx = this.tex;
    const M = (x: number, y: number, z: number, sx = 1, sy = 1, sz = 1, ry = 0) =>
      new THREE.Matrix4().compose(new THREE.Vector3(x, y, z), new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), ry), new THREE.Vector3(sx, sy, sz));
    const floors: THREE.Matrix4[] = [], fT: number[] = [], tall: THREE.Matrix4[] = [], tT: number[] = [], low: THREE.Matrix4[] = [], lT: number[] = [];
    const pillars: THREE.Matrix4[] = [], barrels: THREE.Matrix4[] = [], bones: THREE.Matrix4[] = [];
    const banners: Array<[number, number, number]> = [];
    const torchSpots: THREE.Vector3[] = [];
    for (let j = 0; j < this.H; j++) for (let i = 0; i < this.W; i++) {
      const c = this.cell(i, j), x = i * T, z = j * T;
      if (c !== WALL) {
        floors.push(M(x, -0.25, z));
        const v = 0.78 + r() * 0.3, moss = r() < 0.08;
        fT.push(moss ? v * 0.75 : v, moss ? v * 0.95 : v * 0.97, moss ? v * 0.7 : v);
        if (c === PILLAR) pillars.push(M(x, 0, z));
        if (c === PROP) barrels.push(M(x, 0, z, 1, 1, 1, r() * 6));
        if (c === FLOOR && r() < 0.05) bones.push(M(x + (r() - 0.5) * 1.4, 0.06, z + (r() - 0.5) * 1.4, 1, 1, 1, r() * 6));
        continue;
      }
      let near = false;
      for (let dy = -1; dy <= 1 && !near; dy++) for (let dx = -1; dx <= 1; dx++) if (this.cell(i + dx, j + dy) !== WALL) { near = true; break; }
      if (!near) continue;
      const v = 0.75 + r() * 0.3;
      // Las paredes del lado de la cámara (+x/+z) son bajas para no tapar la acción
      const front = this.cell(i - 1, j) !== WALL || this.cell(i, j - 1) !== WALL || this.cell(i - 1, j - 1) !== WALL;
      if (front) { low.push(M(x, 0.3, z)); lT.push(v, v, v); continue; }
      tall.push(M(x, 1.7, z)); tT.push(v, v * 0.98, v * 1.02);
      const fx = this.cell(i + 1, j) === FLOOR, fz = this.cell(i, j + 1) === FLOOR;
      if ((fx || fz) && (i * 7 + j * 13) % 3 === 0 && r() < 0.75) torchSpots.push(fx ? new THREE.Vector3(x + T / 2 + 0.18, 2.1, z) : new THREE.Vector3(x, 2.1, z + T / 2 + 0.18));
      else if ((fx || fz) && r() < 0.14) banners.push(fx ? [x + T / 2 + 0.03, z, Math.PI / 2] : [x, z + T / 2 + 0.03, 0]);
    }
    this.instanced(new THREE.BoxGeometry(T, 0.5, T), litMat({ color: '#b8b0c0', map: tx.floor, uv: 0.5, tint: true }), floors, fT);
    this.instanced(new THREE.BoxGeometry(T, 3.4, T), litMat({ color: '#a8a0b4', map: tx.wall, uv: 0.5, tint: true }), tall, tT);
    this.instanced(new THREE.BoxGeometry(T, 0.6, T), litMat({ color: '#8a8496', map: tx.wall, uv: 0.5, tint: true }), low, lT);
    const stone = litMat({ color: '#9a94a6', map: tx.wall, uv: 0.7 });
    this.instanced(new THREE.CylinderGeometry(0.5, 0.6, 3.4, 10).translate(0, 1.7, 0), stone, pillars);
    this.instanced(new THREE.BoxGeometry(1.3, 0.35, 1.3).translate(0, 0.17, 0), litMat({ color: '#6c6676' }), pillars.map(m => m.clone()));
    this.instanced(new THREE.CylinderGeometry(0.5, 0.45, 1.1, 10).translate(0, 0.55, 0), litMat({ color: '#7a4a26' }), barrels);
    this.instanced(new THREE.CylinderGeometry(0.53, 0.53, 0.1, 10).translate(0, 0.8, 0), litMat({ color: '#3a3438' }), barrels.map(m => m.clone()));
    this.instanced(new THREE.BoxGeometry(0.7, 0.08, 0.1), litMat({ color: '#d8d0b8' }), bones);
    this.instanced(new THREE.SphereGeometry(0.15, 6, 5).translate(0.42, 0.05, 0), litMat({ color: '#e4dcc4' }), bones.map(m => m.clone()));
    // Estandartes
    const bannerMat = this.track(litMat({ color: '#ffffff', map: tx.banner, meshUv: true, side: THREE.DoubleSide }));
    const bannerGeo = this.track(new THREE.PlaneGeometry(0.95, 1.9));
    for (const [x, z, ry] of banners) { const b = new THREE.Mesh(bannerGeo, bannerMat); b.position.set(x, 1.9, z); b.rotation.y = ry; this.group.add(b); }
    // Antorchas: soporte + llama + halo aditivo
    const holder = this.track(new THREE.CylinderGeometry(0.07, 0.04, 0.55, 6));
    const holderMat = this.track(litMat({ color: '#4a3a2a', emissive: '#1a0c04' }));
    const glowMat = this.track(new THREE.SpriteMaterial({ map: tx.glow, color: lin('#ff9a40'), blending: THREE.AdditiveBlending, depthWrite: false, transparent: true, opacity: 0.55 }));
    const flameMat = this.track(new THREE.SpriteMaterial({ map: tx.flame, color: lin('#ffd27a'), blending: THREE.AdditiveBlending, depthWrite: false, transparent: true }));
    for (const p of torchSpots) {
      const h = new THREE.Mesh(holder, holderMat); h.position.set(p.x, p.y - 0.3, p.z); this.group.add(h);
      const glow = new THREE.Sprite(glowMat); glow.position.copy(p); glow.scale.setScalar(3.2); this.group.add(glow);
      const flame = new THREE.Sprite(flameMat); flame.position.set(p.x, p.y + 0.12, p.z); flame.scale.set(0.5, 0.75, 1); this.group.add(flame);
      this.torches.push({ pos: p.clone(), glow, flame, phase: r() * 10, range: 9 });
    }
  }

  update(t: number) {
    for (const tc of this.torches) {
      const f = 0.85 + Math.sin(t * 9 + tc.phase) * 0.08 + Math.sin(t * 23 + tc.phase * 3) * 0.06;
      tc.glow.scale.setScalar(3.2 * f);
      tc.flame.scale.set(0.5 * f, 0.8 * (0.9 + Math.sin(t * 17 + tc.phase) * 0.12), 1);
    }
  }

  torchFlicker(tc: Torch, t: number) { return 0.82 + Math.sin(t * 9 + tc.phase) * 0.1 + Math.sin(t * 23 + tc.phase * 3) * 0.07; }

  dispose() {
    this.group.parent?.remove(this.group);
    this.disposables.forEach(d => d.dispose());
    this.disposables = [];
  }
}

// Enemigos (esqueleto, murciélago, brujo, gólem y jefe) con IA por campo de flujo, y proyectiles.
import * as THREE from 'three';
import { sound } from './audio';
import { ENEMIES, EnemyDef, EnemyKind } from './config';
import { Dungeon } from './dungeon';
import { Fx } from './fx';
import { buildEnemy, disposeRig, Rig, setRigFx } from './models';
import { Player } from './player';
import { lin, radialTexture } from './three-compat';

type State = 'chase' | 'windup' | 'recover' | 'lunge';
export interface Enemy {
  kind: EnemyKind; def: EnemyDef; rig: Rig; shadow: THREE.Object3D;
  hp: number; maxHp: number; dmg: number; speed: number; cdMul: number;
  state: State; t: number; cd: number; awake: boolean; room: number;
  knock: THREE.Vector3; lungeDir: THREE.Vector3; flash: number; dying: number; phase: number; facing: number;
  struck: boolean; attack: number; bar: THREE.Sprite; fill: THREE.Sprite;
}

export interface EnemyHooks {
  hurtPlayer(dmg: number, from: THREE.Vector3, cause: string): void;
  spellHit(e: Enemy, dmg: number, dir: THREE.Vector3): void;
  summon(kind: EnemyKind, x: number, z: number): void;
  shake(a: number): void;
}

interface Proj { s: THREE.Sprite; vel: THREE.Vector3; life: number; dmg: number; friendly: boolean; color: string; size: number; hits: Set<Enemy> }

const SCREEN_RIGHT = new THREE.Vector3(Math.SQRT1_2, 0, -Math.SQRT1_2);
const v1 = new THREE.Vector3(), v2 = new THREE.Vector3();

export class Enemies {
  list: Enemy[] = [];
  private projs: Proj[] = [];
  private projTex = radialTexture([[0, 'rgba(255,255,255,1)'], [0.22, 'rgba(255,255,255,0.9)'], [0.5, 'rgba(255,255,255,0.3)'], [1, 'rgba(255,255,255,0)']], 64);
  private barBg = new THREE.SpriteMaterial({ color: lin('#120a0e'), depthTest: false, transparent: true, opacity: 0.85 });
  private barFg = new THREE.SpriteMaterial({ color: lin('#e8384a'), depthTest: false });

  constructor(private group: THREE.Group, private fx: Fx) {}

  spawn(kind: EnemyKind, x: number, z: number, room: number, hpMul: number, dmgMul: number, awake = false) {
    const def = ENEMIES[kind], rig = buildEnemy(kind);
    const shadow = this.fx.shadow(def.radius * (kind === 'bat' ? 0.7 : 1));
    rig.root.add(shadow);
    rig.root.position.set(x, 0, z);
    const bar = new THREE.Sprite(this.barBg), fill = new THREE.Sprite(this.barFg);
    const h = kind === 'golem' ? 3.0 : kind === 'bat' ? 2.0 : 2.3;
    bar.scale.set(1.2, 0.14, 1); bar.position.y = h; fill.center.set(0, 0.5); fill.scale.set(1.12, 0.09, 1);
    fill.position.set(-0.56 * SCREEN_RIGHT.x, h, -0.56 * SCREEN_RIGHT.z);
    bar.visible = fill.visible = false; bar.renderOrder = 8; fill.renderOrder = 9;
    rig.root.add(bar, fill);
    this.group.add(rig.root);
    const e: Enemy = {
      kind, def, rig, shadow, hp: def.hp * hpMul, maxHp: def.hp * hpMul, dmg: def.dmg * dmgMul, speed: def.speed * (0.92 + Math.random() * 0.16),
      cdMul: 1, state: 'chase', t: 0, cd: 0.6 + Math.random(), awake, room, knock: new THREE.Vector3(), lungeDir: new THREE.Vector3(),
      flash: 0, dying: 0, phase: Math.random() * 10, facing: Math.random() * 6, struck: false, attack: 0, bar, fill,
    };
    if (kind === 'boss') rig.root.scale.setScalar(1.15);
    this.list.push(e);
    return e;
  }

  get alive() { return this.list.filter(e => e.dying <= 0); }

  /** Aplica daño; devuelve true si lo mata. */
  damage(e: Enemy, dmg: number, dir: THREE.Vector3, knock: number) {
    if (e.dying > 0) return false;
    e.hp -= dmg; e.flash = 1; e.awake = true;
    const kb = e.kind === 'golem' || e.kind === 'boss' ? knock * 0.2 : knock;
    e.knock.addScaledVector(dir, kb);
    if (e.state === 'windup' && e.kind !== 'golem' && e.kind !== 'boss' && dmg > e.maxHp * 0.3) { e.state = 'recover'; e.t = 0.3; }
    if (e.hp <= 0) { e.dying = 0.55; e.bar.visible = e.fill.visible = false; return true; }
    if (e.kind !== 'boss') { e.bar.visible = e.fill.visible = true; e.fill.scale.x = 1.12 * Math.max(0, e.hp / e.maxHp); }
    return false;
  }

  shoot(x: number, y: number, z: number, dx: number, dz: number, speed: number, dmg: number, friendly: boolean, color: string, size = 1.1) {
    let p = this.projs.find(q => q.life <= 0);
    if (!p) {
      if (this.projs.length >= 60) return;
      const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.projTex, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true }));
      s.renderOrder = 6; this.group.add(s);
      p = { s, vel: new THREE.Vector3(), life: 0, dmg: 0, friendly, color, size, hits: new Set() };
      this.projs.push(p);
    }
    const l = Math.hypot(dx, dz) || 1;
    p.vel.set(dx / l * speed, 0, dz / l * speed); p.life = friendly ? 1.3 : 3.2; p.dmg = dmg; p.friendly = friendly;
    p.color = color; p.size = size; p.hits.clear();
    p.s.material.color.copy(lin(color)); p.s.position.set(x, y, z); p.s.scale.setScalar(size); p.s.visible = true;
  }

  update(dt: number, t: number, d: Dungeon, pl: Player, hooks: EnemyHooks, playerRoom: number) {
    const pp = pl.pos;
    for (const e of this.list) {
      const P = e.rig.p, root = e.rig.root, pos = root.position;
      if (e.dying > 0) {
        e.dying -= dt;
        const k = Math.max(0, e.dying / 0.55);
        root.scale.setScalar((e.kind === 'boss' ? 1.15 : 1) * (0.3 + 0.7 * k)); e.rig.body.position.y = -(1 - k) * 0.6;
        e.rig.body.rotation.z = (1 - k) * 1.2;
        setRigFx(e.rig, k * 0.8, 0);
        if (Math.random() < 0.6) this.fx.spawn(pos.x, 0.8, pos.z, 1, e.kind === 'boss' ? '#5ae0ff' : '#b07aff', 2, 0.6, 0.3, { up: 1.2, grav: -1 });
        continue;
      }
      e.phase += dt; e.cd -= dt; e.flash = Math.max(0, e.flash - dt * 5);
      if (e.knock.lengthSq() > 0.001) { pos.addScaledVector(e.knock, dt); e.knock.multiplyScalar(Math.max(0, 1 - dt * 9)); }
      const dx = pp.x - pos.x, dz = pp.z - pos.z, dist = Math.hypot(dx, dz);
      if (!e.awake) {
        if (e.room === playerRoom || (dist < 11 && d.los(pos.x, pos.z, pp.x, pp.z))) e.awake = true;
        this.idleAnim(e, t);
        continue;
      }
      let mx = 0, mz = 0, warn = 0, turn = 8;
      const reach = e.def.reach + pl.radius;
      if (e.state === 'chase') {
        const see = d.los(pos.x, pos.z, pp.x, pp.z);
        let want = 1;
        if (e.kind === 'warlock') want = !see ? 1 : dist < 4.5 ? -1 : dist > 7.5 ? 1 : 0;
        if (want !== 0 && dist > e.def.radius + pl.radius + 0.1) {
          if (see || want < 0) { mx = dx / dist * want; mz = dz / dist * want; }
          else if (d.flowDir(pos.x, pos.z, v1)) { mx = v1.x; mz = v1.z; }
        } else if (e.kind === 'warlock') { mx = -dz / dist * 0.6; mz = dx / dist * 0.6; if (Math.sin(e.phase * 0.7) < 0) { mx = -mx; mz = -mz; } }
        if (e.kind === 'bat') { const w = Math.sin(e.phase * 5) * 0.7; mx += -dz / (dist || 1) * w; mz += dx / (dist || 1) * w; }
        if (e.cd <= 0 && see && (dist < reach || (e.kind === 'boss' && dist < 13))) this.beginAttack(e, dist);
      } else if (e.state === 'windup') {
        e.t -= dt; warn = 1 - Math.max(0, e.t) / this.windupTime(e);
        turn = e.kind === 'golem' ? 2 : 6;
        if (e.t <= 0) this.strike(e, dist, dx, dz, hooks);
      } else if (e.state === 'lunge') {
        e.t -= dt; turn = 0;
        mx = e.lungeDir.x * 2.6; mz = e.lungeDir.z * 2.6;
        if (!e.struck && dist < e.def.radius + pl.radius + 0.3) { e.struck = true; hooks.hurtPlayer(e.dmg, pos, e.def.name); }
        if (e.t <= 0) { e.state = 'recover'; e.t = 0.5; }
      } else {
        e.t -= dt;
        if (e.kind === 'bat' && dist < 4) { mx = -dx / dist; mz = -dz / dist; }
        if (e.t <= 0) e.state = 'chase';
      }
      const sp = e.speed * (e.kind === 'boss' && e.hp < e.maxHp * 0.5 ? 1.35 : 1);
      pos.x += mx * sp * dt; pos.z += mz * sp * dt;
      if (turn > 0 && dist > 0.01) {
        let da = Math.atan2(dx, dz) - e.facing; da = Math.atan2(Math.sin(da), Math.cos(da));
        e.facing += da * Math.min(1, dt * turn);
      }
      root.rotation.y = e.facing;
      this.anim(e, t, Math.min(1, Math.hypot(mx, mz)), warn);
      setRigFx(e.rig, e.flash, warn * (0.6 + 0.4 * Math.sin(t * 30)));
    }
    // separación entre enemigos + colisión con paredes
    const al = this.list;
    for (let i = 0; i < al.length; i++) {
      const a = al[i]; if (a.dying > 0 || !a.awake) continue;
      for (let j = i + 1; j < al.length; j++) {
        const b = al[j]; if (b.dying > 0) continue;
        const ax = b.rig.root.position.x - a.rig.root.position.x, az = b.rig.root.position.z - a.rig.root.position.z;
        const r = a.def.radius + b.def.radius, d2 = ax * ax + az * az;
        if (d2 < r * r && d2 > 1e-6) {
          const dd = Math.sqrt(d2), push = (r - dd) * 0.5;
          a.rig.root.position.x -= ax / dd * push; a.rig.root.position.z -= az / dd * push;
          b.rig.root.position.x += ax / dd * push; b.rig.root.position.z += az / dd * push;
        }
      }
      d.collide(a.rig.root.position, a.def.radius);
    }
    this.list = this.list.filter(e => { if (e.dying > 0 || e.hp > 0) return true; if (e.dying <= 0) { disposeRig(e.rig); return false; } return true; });
    this.updateProjectiles(dt, d, pl, hooks);
  }

  private windupTime(e: Enemy) { return e.def.windup * (e.kind === 'boss' && e.attack === 1 ? 1.2 : 1); }

  private beginAttack(e: Enemy, dist: number) {
    if (e.kind === 'boss') {
      const options = dist < 4.5 ? [0, 1, 2, 0] : [1, 2, 3, 2];
      e.attack = options[Math.floor(Math.random() * options.length)];
      if (e.attack === 3 && this.alive.length > 8) e.attack = 2;
      if (e.attack === 0) this.fx.ring(e.rig.root.position.x, e.rig.root.position.z, 4.5, this.windupTime(e), '#40d8ff', true);
      if (e.attack === 1) sound.roar();
    }
    if (e.kind === 'golem') this.fx.ring(e.rig.root.position.x, e.rig.root.position.z, 3.2, e.def.windup, '#ff5a1a', true);
    e.state = 'windup'; e.t = this.windupTime(e);
  }

  private strike(e: Enemy, dist: number, dx: number, dz: number, hooks: EnemyHooks) {
    const pos = e.rig.root.position;
    e.state = 'recover'; e.t = 0.45; e.cd = e.def.cd * (0.8 + Math.random() * 0.4) * e.cdMul;
    const fwdX = Math.sin(e.facing), fwdZ = Math.cos(e.facing);
    if (e.kind === 'skeleton') {
      sound.swing();
      const ang = dist > 0 ? (dx * fwdX + dz * fwdZ) / dist : 1;
      if (dist < e.def.reach + 0.9 && ang > 0.3) hooks.hurtPlayer(e.dmg, pos, e.def.name);
      this.fx.spawn(pos.x + fwdX * 1.2, 1, pos.z + fwdZ * 1.2, 5, '#ffe2b0', 3, 0.25, 0.25);
    } else if (e.kind === 'bat') {
      e.state = 'lunge'; e.t = 0.32; e.struck = false; e.lungeDir.set(dx, 0, dz).normalize();
    } else if (e.kind === 'warlock') {
      sound.fireball();
      const n = this.floorSpread, base = Math.atan2(dx, dz);
      for (let k = 0; k < n; k++) { const a = base + (k - (n - 1) / 2) * 0.22; this.shoot(pos.x + fwdX * 0.6, 1.4, pos.z + fwdZ * 0.6, Math.sin(a), Math.cos(a), 7.5, e.dmg, false, '#7dff4a'); }
    } else if (e.kind === 'golem' || (e.kind === 'boss' && e.attack === 0)) {
      const R = e.kind === 'golem' ? 3.2 : 4.5;
      sound.boom(); hooks.shake(e.kind === 'golem' ? 0.5 : 0.8);
      this.fx.ring(pos.x, pos.z, R + 1, 0.45, e.kind === 'golem' ? '#ffb070' : '#a0f0ff');
      this.fx.spawn(pos.x, 0.3, pos.z, 30, e.kind === 'golem' ? '#c0a080' : '#60d8ff', 7, 0.6, 0.45, { up: 0.5 });
      if (dist < R + 0.3) hooks.hurtPlayer(e.dmg, pos, e.def.name);
      if (e.kind === 'golem') e.t = 0.8;
    } else if (e.kind === 'boss') {
      const rage = e.hp < e.maxHp * 0.5;
      e.cdMul = rage ? 0.65 : 1;
      if (e.attack === 1) {
        const n = rage ? 20 : 14, off = Math.random();
        sound.fireball(); hooks.shake(0.3);
        for (let k = 0; k < n; k++) { const a = (k + off) / n * Math.PI * 2; this.shoot(pos.x, 1.6, pos.z, Math.sin(a), Math.cos(a), 6, e.dmg * 0.7, false, '#3ad8ff', 1.3); }
      } else if (e.attack === 2) {
        sound.fireball();
        const base = Math.atan2(dx, dz), n = rage ? 5 : 3;
        for (let k = 0; k < n; k++) { const a = base + (k - (n - 1) / 2) * 0.25; this.shoot(pos.x + fwdX, 2.2, pos.z + fwdZ, Math.sin(a), Math.cos(a), 9, e.dmg * 0.8, false, '#7af0ff', 1.4); }
      } else {
        sound.roar();
        for (let k = 0; k < 2; k++) { const a = Math.random() * Math.PI * 2; hooks.summon(rage && k === 1 ? 'bat' : 'skeleton', pos.x + Math.sin(a) * 2.5, pos.z + Math.cos(a) * 2.5); }
        this.fx.flash(pos.x, 2, pos.z, 8, '#40c8ff', 0.5);
      }
    }
  }

  floorSpread = 1;

  idleAll(t: number) { this.list.forEach(e => this.idleAnim(e, t)); }

  private idleAnim(e: Enemy, t: number) {
    const P = e.rig.p;
    if (e.kind === 'bat') { P.core.position.y = 1.3 + Math.sin(t * 3 + e.phase) * 0.15; const f = Math.sin(t * 18 + e.phase) * 0.8; P.wingL.rotation.z = f; P.wingR.rotation.z = -f; }
    else e.rig.body.position.y = Math.sin(t * 2 + e.phase) * 0.03;
    if (e.kind === 'boss') { P.orbit.rotation.y = t * 1.5; e.rig.body.position.y = 0.3 + Math.sin(t * 1.6) * 0.15; }
    setRigFx(e.rig, 0, 0);
  }

  private anim(e: Enemy, t: number, move: number, warn: number) {
    const P = e.rig.p, w = Math.sin(t * (e.kind === 'golem' ? 5 : 10) + e.phase) * 0.6 * move;
    if (P.legL) { P.legL.rotation.x = w; P.legR.rotation.x = -w; }
    if (e.kind === 'bat') {
      const f = Math.sin(t * 22 + e.phase) * 0.9; P.wingL.rotation.z = f; P.wingR.rotation.z = -f;
      P.core.position.y = 1.3 + Math.sin(t * 4 + e.phase) * 0.2 - (e.state === 'lunge' ? 0.4 : 0);
      return;
    }
    if (e.kind === 'boss') {
      P.orbit.rotation.y = t * (e.hp < e.maxHp * 0.5 ? 3 : 1.5);
      e.rig.body.position.y = 0.3 + Math.sin(t * 1.6) * 0.15;
      P.arm.rotation.x = -warn * 2.2; P.arm2.rotation.x = -warn * 1.6;
      if (Math.random() < 0.3) this.fx.embers(e.rig.root.position.x + (Math.random() - 0.5) * 2, 0.4, e.rig.root.position.z + (Math.random() - 0.5) * 2, '#40c8ff');
      return;
    }
    e.rig.body.position.y = Math.abs(w) * 0.06;
    if (e.state === 'windup') { if (P.arm) P.arm.rotation.x = -warn * 2.6; if (P.arm2 && e.kind === 'golem') P.arm2.rotation.x = -warn * 2.6; }
    else if (P.arm) {
      const target = e.state === 'recover' && e.kind !== 'warlock' ? -0.9 : -w * 0.5;
      P.arm.rotation.x += (target - P.arm.rotation.x) * 0.3;
      if (P.arm2) P.arm2.rotation.x += ((e.kind === 'golem' && e.state === 'recover' ? -0.9 : w * 0.5) - P.arm2.rotation.x) * 0.3;
    }
    if (e.kind === 'warlock' && Math.random() < 0.25) {
      const o = P.orb.getWorldPosition(v2); this.fx.embers(o.x, o.y, o.z, '#7dff4a');
    }
  }

  private updateProjectiles(dt: number, d: Dungeon, pl: Player, hooks: EnemyHooks) {
    for (const p of this.projs) {
      if (p.life <= 0) continue;
      p.life -= dt;
      const s = p.s.position;
      s.addScaledVector(p.vel, dt);
      p.s.scale.setScalar(p.size * (0.9 + Math.random() * 0.2));
      if (Math.random() < 0.7) this.fx.spawn(s.x, s.y, s.z, 1, p.color, 0.5, 0.35, p.size * 0.35, { up: 0.2, grav: 0 });
      let end = !d.walkable(s.x, s.z) || p.life <= 0;
      if (!end && p.friendly) {
        for (const e of this.list) {
          if (e.dying > 0 || p.hits.has(e)) continue;
          const ep = e.rig.root.position;
          if (Math.hypot(ep.x - s.x, ep.z - s.z) < e.def.radius + 0.5) { p.hits.add(e); hooks.spellHit(e, p.dmg, v1.copy(p.vel).normalize()); }
        }
      } else if (!end && Math.hypot(pl.pos.x - s.x, pl.pos.z - s.z) < pl.radius + 0.35 && pl.vulnerable) {
        hooks.hurtPlayer(p.dmg, s, 'Hechizo'); end = true;
      }
      if (end) { p.life = 0; p.s.visible = false; this.fx.spawn(s.x, s.y, s.z, 10, p.color, 4, 0.4, 0.35); this.fx.flash(s.x, s.y, s.z, 2.4, p.color, 0.25); }
    }
  }

  /** Proyectiles activos (para iluminar con su color). */
  activeProjectiles() { return this.projs.filter(p => p.life > 0).map(p => ({ pos: p.s.position, color: p.color })); }

  clear() {
    this.list.forEach(e => disposeRig(e.rig)); this.list = [];
    this.projs.forEach(p => { p.life = 0; p.s.visible = false; });
  }

  dispose() {
    this.clear();
    this.projs.forEach(p => p.s.material.dispose());
    this.projTex.dispose(); this.barBg.dispose(); this.barFg.dispose();
  }
}

// Motor: escena isométrica, bucle, combate, pisos, iluminación dinámica de antorchas y estado de la partida.
import * as THREE from 'three';
import { sound } from './audio';
import { baseStats, BOSS_EVERY, Difficulty, DIFFS, EnemyKind, mulberry32, Rng, rollUpgrades, RunResult, Upgrade } from './config';
import { Dungeon, DungeonTextures, makeDungeonTextures, Room, TILE } from './dungeon';
import { Enemies, Enemy } from './enemies';
import { Fx } from './fx';
import { Input } from './input';
import { Loot } from './loot';
import { disposeModelCache } from './models';
import { ATTACK_ARC, ATTACK_RANGE, Player } from './player';
import { lightUniforms, MAX_LIGHTS, setupRenderer } from './three-compat';

export interface HudState {
  hp: number; maxHp: number; gold: number; score: number; floor: number; kills: number;
  spell: number; spellMax: number; dodge: number; combo: number; left: number;
  boss: { name: string; hp: number; max: number } | null;
}
export interface GameEvents {
  onHud(h: HudState): void; onToast(text: string, color: string): void;
  onUpgrade(choices: Upgrade[]): void; onOver(r: RunResult): void; onHurt(): void;
}
type Mode = 'attract' | 'play' | 'paused' | 'upgrade' | 'dying' | 'over';

const CAM_DIR = new THREE.Vector3(1, 1.3, 1).normalize();
const HIT_COLORS: Record<EnemyKind, string> = { skeleton: '#f0e2c0', bat: '#c070ff', warlock: '#8dff5a', golem: '#ffa050', boss: '#5ae0ff' };
const tmp = new THREE.Vector3(), tmp2 = new THREE.Vector3();

export class Game {
  readonly input = new Input();
  private renderer: THREE.WebGLRenderer;
  private scene = new THREE.Scene();
  private camera = new THREE.OrthographicCamera(-10, 10, 10, -10, 0.1, 200);
  private world = new THREE.Group();
  private tex: DungeonTextures;
  private fx = new Fx();
  private enemies: Enemies;
  private loot: Loot;
  private player: Player;
  private dungeon: Dungeon | null = null;
  private mode: Mode = 'attract';
  private diff: Difficulty = DIFFS[1];
  private rng: Rng = mulberry32(7);
  private floor = 1; private score = 0; private gold = 0; private kills = 0; private time = 0;
  private combo = 0; private comboT = 0; private hitstop = 0; private shake = 0; private flashL = 0;
  private spellRegen = 0; private dyingT = 0; private hudT = 0; private flowT = 0; private bossAnnounced = false;
  private boss: Enemy | null = null;
  private camTarget = new THREE.Vector3();
  private viewH = 17;
  private raf = 0; private clock = new THREE.Clock(); private t = 0;
  private ro: ResizeObserver;

  constructor(private host: HTMLElement, private ev: GameEvents) {
    this.renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
    setupRenderer(this.renderer);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    this.renderer.setClearColor(0x06050a, 1);
    host.appendChild(this.renderer.domElement);
    this.renderer.domElement.style.display = 'block';
    this.scene.background = new THREE.Color(0x06050a);
    this.scene.add(this.world, this.fx.group);
    this.tex = makeDungeonTextures();
    this.enemies = new Enemies(this.world, this.fx);
    this.loot = new Loot(this.world, this.fx, this.tex.rune);
    this.player = new Player(baseStats(100), this.fx.shadow(0.5));
    this.world.add(this.player.rig.root);
    this.ro = new ResizeObserver(() => this.resize());
    this.ro.observe(host);
    this.resize();
    this.loop();
  }

  // ---------------- Ciclo de partida ----------------
  toAttract() {
    this.mode = 'attract'; this.rng = mulberry32(20240);
    this.floor = 1; this.buildFloor(this.diff);
    this.input.reset();
  }

  newRun(diff: Difficulty) {
    this.diff = diff; this.rng = mulberry32((Math.random() * 1e9) | 0);
    this.floor = 1; this.score = 0; this.gold = 0; this.kills = 0; this.time = 0; this.combo = 0;
    this.player.reset(baseStats(diff.playerHp), 0, 0);
    this.buildFloor(diff);
    this.mode = 'play'; this.input.reset(); this.clock.getDelta();
    this.ev.onToast('Piso 1 — La Cripta Olvidada', '#ffb45a');
    this.emitHud();
  }

  setPaused(p: boolean) { if (this.mode === 'play' && p) this.mode = 'paused'; else if (this.mode === 'paused' && !p) { this.mode = 'play'; this.clock.getDelta(); } }

  chooseUpgrade(u: Upgrade) {
    const s = this.player.stats;
    u.apply(s);
    if (u.id === 'vida') this.player.hp = s.maxHp;
    if (u.id === 'arcano') this.player.spell = s.spellMax;
    sound.levelUp(); this.ev.onToast(u.name, u.color);
    this.mode = 'play'; this.input.reset(); this.clock.getDelta(); this.emitHud();
  }

  private buildFloor(diff: Difficulty) {
    this.enemies.clear(); this.loot.clear(); this.fx.clear();
    this.dungeon?.dispose();
    const d = new Dungeon(this.floor, this.rng, this.tex);
    this.dungeon = d; this.world.add(d.group);
    this.boss = null; this.bossAnnounced = false;
    const st = d.start;
    this.player.pos.set(st.cx, 0, st.cz);
    if (this.mode === 'attract') this.player.reset(baseStats(100), st.cx, st.cz);
    this.enemies.floorSpread = this.floor >= 3 ? 3 : 1;
    const hpM = diff.hp * (1 + 0.18 * (this.floor - 1)), dmM = diff.dmg * (1 + 0.08 * (this.floor - 1));
    const isBoss = this.floor % BOSS_EVERY === 0;
    const pickKind = (): EnemyKind => {
      const r = this.rng(), f = this.floor;
      if (f >= 2 && r < 0.14) return 'golem';
      if (r < 0.36) return 'bat';
      if (r < 0.36 + Math.min(0.3, 0.12 + f * 0.04)) return 'warlock';
      return 'skeleton';
    };
    for (const room of d.rooms) {
      for (let k = 0, n = 2 + Math.floor(this.rng() * 3); k < n; k++) { const s = d.randomSpot(room, 0, { x: st.cx, z: st.cz }, 3); this.loot.addVase(s.x, s.z); }
      if (room.kind === 'start') {
        // Bienvenida inmediata: enemigos visibles cerca del héroe
        const around: Array<[EnemyKind, number, number]> = [['skeleton', -4.5, -1.5], ['skeleton', -1.5, -4.8], ['bat', 3.5, -3.5]];
        if (this.floor > 1) around.push(['warlock', -5, -5]);
        for (const [k, ox, oz] of around) this.enemies.spawn(k, st.cx + ox, st.cz + oz, room.id, hpM, dmM);
        continue;
      }
      if (room.kind === 'stairs' && isBoss) {
        this.boss = this.enemies.spawn('boss', room.cx, room.cz, room.id, diff.hp * (1 + 0.35 * (this.floor / BOSS_EVERY - 1)), dmM);
        continue;
      }
      if (room.kind === 'treasure') this.loot.addChest(room.cx, room.cz, Math.PI * 0.25);
      const n = Math.round((2 + this.floor * 0.6 + this.rng() * 2) * diff.count);
      for (let k = 0; k < n; k++) { const s = this.spotIn(d, room); this.enemies.spawn(pickKind(), s.x, s.z, room.id, hpM, dmM); }
    }
    this.loot.setStairs(d.stairsRoom.cx, d.stairsRoom.cz, !isBoss);
    this.camTarget.set(st.cx, 0, st.cz);
    d.updateFlow(st.cx, st.cz);
    if (isBoss && this.mode !== 'attract') this.ev.onToast('Un poder antiguo acecha en este piso…', '#5ae0ff');
  }

  private spotIn(d: Dungeon, room: Room) { return d.randomSpot(room, 1, room.kind === 'treasure' ? { x: room.cx, z: room.cz } : undefined, 2); }

  private nextFloor() {
    this.floor++;
    this.score += 250 * this.floor;
    this.player.heal(this.player.stats.maxHp * 0.2);
    sound.stairs();
    this.buildFloor(this.diff);
    this.ev.onToast(this.floor % BOSS_EVERY === 0 ? `Piso ${this.floor} — Trono del Liche` : `Piso ${this.floor}`, '#ffb45a');
  }

  // ---------------- Combate ----------------
  private nearestEnemy(max: number) {
    let best: Enemy | null = null, bd = max;
    for (const e of this.enemies.list) {
      if (e.dying > 0) continue;
      const d = e.rig.root.position.distanceTo(this.player.pos);
      if (d < bd) { bd = d; best = e; }
    }
    return best;
  }

  private playerAttack() {
    const pl = this.player;
    const tgt = this.nearestEnemy(4.2);
    if (tgt) pl.face(tgt.rig.root.position.x - pl.pos.x, tgt.rig.root.position.z - pl.pos.z, true);
    if (!pl.tryAttack()) return;
    sound.swing();
    const f = pl.forward(tmp), cosA = Math.cos(ATTACK_ARC / 2);
    const inArc = (x: number, z: number, rad: number) => {
      const dx = x - pl.pos.x, dz = z - pl.pos.z, d = Math.hypot(dx, dz);
      return d < ATTACK_RANGE + rad && (d < rad + 0.7 || (dx * f.x + dz * f.z) / d > cosA);
    };
    let hits = 0;
    for (const e of this.enemies.list) {
      if (e.dying > 0) continue;
      const p = e.rig.root.position;
      if (!inArc(p.x, p.z, e.def.radius)) continue;
      const crit = Math.random() < pl.stats.crit;
      const dmg = pl.stats.dmg * (crit ? 2 : 1) * (0.9 + Math.random() * 0.2);
      this.damageEnemy(e, dmg, tmp2.set(p.x - pl.pos.x, 0, p.z - pl.pos.z).normalize(), crit, 7);
      hits++;
    }
    if (this.loot.smash((x, z) => inArc(x, z, 0.4))) sound.vase();
    if (hits) { this.hitstop = 0.06; this.shake = Math.max(this.shake, 0.18); }
  }

  private damageEnemy(e: Enemy, dmg: number, dir: THREE.Vector3, crit: boolean, knock: number) {
    const p = e.rig.root.position;
    sound.hit(crit);
    this.fx.hit(p.x, p.z, HIT_COLORS[e.kind], crit);
    if (crit) this.fx.flash(p.x, 1.2, p.z, 3, '#fff0c0', 0.2);
    const pl = this.player;
    if (pl.stats.lifesteal > 0) pl.heal(dmg * pl.stats.lifesteal);
    if (this.enemies.damage(e, dmg, dir, knock)) this.onKill(e);
  }

  private onKill(e: Enemy) {
    const p = e.rig.root.position;
    this.kills++; this.combo++; this.comboT = 3;
    this.score += Math.round(e.def.score * (1 + Math.min(this.combo, 10) * 0.1) * (1 + this.floor * 0.1));
    sound.die();
    this.fx.spawn(p.x, 1, p.z, 22, HIT_COLORS[e.kind], 6, 0.8, 0.45);
    const [a, b] = e.def.gold;
    this.loot.scatterGold(p.x, p.z, a + Math.floor(Math.random() * (b - a + 1)));
    if (Math.random() < 0.09) this.loot.drop('potion', p.x, p.z, 25);
    if (Math.random() < 0.06) this.loot.drop('crystal', p.x, p.z);
    if (this.combo >= 3 && this.combo % 3 === 0) this.ev.onToast(`¡Combo x${this.combo}!`, '#ffd24a');
    if (e.kind === 'boss') {
      this.shake = 1.2; this.flashL = 1; sound.boom();
      this.fx.flash(p.x, 2, p.z, 14, '#5ae0ff', 0.9);
      for (let k = 0; k < 3; k++) this.loot.drop('potion', p.x, p.z, 40);
      this.loot.setStairs(p.x, p.z, true);
      this.boss = null;
      this.ev.onToast('¡Rey Liche derrotado! La escalera se abre', '#5ae0ff');
    }
  }

  private castSpell() {
    const pl = this.player;
    if (pl.spell <= 0 || pl.dodging) { if (pl.spell <= 0) this.ev.onToast('Sin cargas de hechizo', '#a78bfa'); return; }
    pl.spell--;
    const tgt = this.nearestEnemy(14);
    if (tgt) pl.face(tgt.rig.root.position.x - pl.pos.x, tgt.rig.root.position.z - pl.pos.z, true);
    const f = pl.forward(tmp);
    this.enemies.shoot(pl.pos.x + f.x, 1.2, pl.pos.z + f.z, f.x, f.z, 17, pl.stats.dmg * 1.8, true, '#9ad8ff', 1.6);
    sound.spell(); this.fx.flash(pl.pos.x + f.x, 1.2, pl.pos.z + f.z, 3, '#9ad8ff', 0.25);
  }

  private hurtPlayer(dmg: number, from: THREE.Vector3, cause: string) {
    const pl = this.player;
    if (this.mode !== 'play' || !pl.hurt(Math.round(dmg))) return;
    sound.hurt(); this.shake = Math.max(this.shake, 0.4); this.combo = 0;
    this.fx.spawn(pl.pos.x, 1, pl.pos.z, 14, '#ff3040', 5, 0.5, 0.4);
    const kx = pl.pos.x - from.x, kz = pl.pos.z - from.z, kl = Math.hypot(kx, kz) || 1;
    pl.pos.x += kx / kl * 0.5; pl.pos.z += kz / kl * 0.5;
    this.ev.onHurt();
    if (pl.hp <= 0) { this.mode = 'dying'; this.dyingT = 1.4; this.deathCause = cause; sound.roar(); }
  }
  private deathCause = '';

  // ---------------- Actualización ----------------
  private update(dt: number) {
    const d = this.dungeon; if (!d) return;
    this.t += dt;
    d.update(this.t);
    if (this.mode === 'attract') {
      const st = d.start, a = this.t * 0.15;
      this.camTarget.set(st.cx + Math.cos(a) * 3, 0, st.cz + Math.sin(a) * 3);
      this.enemies.idleAll(this.t);
      this.player.update(dt, 0, 0, d, this.t);
      this.fx.update(dt); this.updateLights(); return;
    }
    if (this.mode === 'dying') {
      this.dyingT -= dt;
      const k = 1 - Math.max(0, this.dyingT) / 1.4;
      this.player.rig.body.rotation.z = k * 1.5; this.player.rig.body.position.y = -k * 0.3;
      this.fx.update(dt); this.updateLights();
      if (this.dyingT <= 0) {
        this.mode = 'over';
        this.ev.onOver({ score: this.score, floor: this.floor, kills: this.kills, gold: this.gold, time: this.time, cause: this.deathCause });
      }
      return;
    }
    if (this.mode !== 'play') return;
    this.time += dt;
    const pl = this.player, inp = this.input;
    const wdt = this.hitstop > 0 ? dt * 0.15 : dt;
    this.hitstop = Math.max(0, this.hitstop - dt);
    const mv = inp.move();
    if (inp.dodgePressed() && pl.tryDodge(mv.x, mv.z)) { sound.dodge(); this.fx.spawn(pl.pos.x, 0.3, pl.pos.z, 10, '#a0b0c8', 3, 0.4, 0.4, { up: 0.3 }); }
    if (inp.attackPressed() || (inp.attackHeld() && pl.atkCd <= 0)) this.playerAttack();
    if (inp.spellPressed()) this.castSpell();
    pl.update(wdt, mv.x, mv.z, d, this.t);
    if (pl.dodging && Math.random() < 0.6) this.fx.spawn(pl.pos.x, 0.6, pl.pos.z, 1, '#8fa8ff', 0.5, 0.35, 0.5, { grav: 0 });
    this.spellRegen += dt;
    if (this.spellRegen > 14) { this.spellRegen = 0; if (pl.spell < pl.stats.spellMax) pl.spell++; }
    this.flowT -= dt;
    if (this.flowT <= 0) { this.flowT = 0.25; d.updateFlow(pl.pos.x, pl.pos.z); }
    this.enemies.update(wdt, this.t, d, pl, {
      hurtPlayer: (dmg, from, cause) => this.hurtPlayer(dmg, from, cause),
      spellHit: (e, dmg, dir) => this.damageEnemy(e, dmg, dir, false, 9),
      summon: (k, x, z) => {
        if (!d.walkable(x, z)) return;
        const e = this.enemies.spawn(k, x, z, -1, this.diff.hp * (1 + 0.18 * (this.floor - 1)), this.diff.dmg, true);
        this.fx.spawn(x, 0.5, z, 18, '#40c8ff', 4, 0.6, 0.4, { up: 1 }); e.cd = 1;
      },
      shake: a => { this.shake = Math.max(this.shake, a); },
    }, d.roomAt(pl.pos.x, pl.pos.z));
    if (this.boss && this.boss.awake && !this.bossAnnounced) { this.bossAnnounced = true; sound.roar(); this.ev.onToast('¡El Rey Liche despierta!', '#5ae0ff'); this.shake = 0.6; }
    this.loot.update(wdt, this.t, pl, {
      gold: v => { this.gold += v; this.score += 10 * v; sound.coin(); },
      heal: v => { pl.heal(v); sound.potion(); this.ev.onToast(`+${v} vida`, '#ff5a6a'); },
      crystal: () => { pl.spell = Math.min(pl.stats.spellMax, pl.spell + 1); sound.potion(); this.ev.onToast('+1 hechizo', '#b48aff'); },
      chest: () => { sound.chest(); this.mode = 'upgrade'; this.input.reset(); this.ev.onUpgrade(rollUpgrades(3)); },
    });
    if (this.loot.nearStairs(pl.pos.x, pl.pos.z) && this.mode === 'play') this.nextFloor();
    if (this.comboT > 0) { this.comboT -= dt; if (this.comboT <= 0) this.combo = 0; }
    this.camTarget.lerp(tmp.set(pl.pos.x, 0, pl.pos.z), Math.min(1, dt * 6));
    this.fx.update(dt);
    if (Math.random() < 0.3) this.fx.embers(pl.pos.x + (Math.random() - 0.5) * 12, 0.2, pl.pos.z + (Math.random() - 0.5) * 12, '#ff9a4a');
    this.updateLights();
    this.hudT -= dt;
    if (this.hudT <= 0) { this.hudT = 0.1; this.emitHud(); }
  }

  /** Asigna los huecos de luz: héroe, antorchas más cercanas, escalera, proyectiles y destellos. */
  private updateLights() {
    const d = this.dungeon!; const P = lightUniforms.uLP.value, C = lightUniforms.uLC.value, R = lightUniforms.uLR.value;
    for (let i = 0; i < MAX_LIGHTS; i++) { P[i].set(0, -99, 0); C[i].set(0, 0, 0); R[i] = 1; }
    const pl = this.player.pos, ct = this.camTarget;
    const hurt = this.player.flash;
    P[0].set(pl.x, 2.8, pl.z); C[0].set(1.25 + hurt, 0.85 - hurt * 0.4, 0.55 - hurt * 0.3); R[0] = 10.5;
    const near = d.torches.map(tc => ({ tc, dd: tc.pos.distanceToSquared(ct) })).sort((a, b) => a.dd - b.dd).slice(0, 8);
    near.forEach(({ tc }, k) => {
      const f = d.torchFlicker(tc, this.t);
      P[1 + k].copy(tc.pos); P[1 + k].y -= 0.2; C[1 + k].set(2.0 * f, 0.95 * f, 0.35 * f); R[1 + k] = tc.range;
    });
    if (this.loot.stairsActive) { P[9].set(this.loot.stairs.position.x, 1.2, this.loot.stairs.position.z); C[9].set(0.35, 0.8, 2.0); R[9] = 8; }
    const boss = this.boss;
    if (boss && boss.dying <= 0) { const b = boss.rig.root.position; P[10].set(b.x, 3, b.z); C[10].set(0.3, 1.1, 1.6); R[10] = 9; }
    else {
      const pr = this.enemies.activeProjectiles().sort((a, b) => a.pos.distanceToSquared(pl) - b.pos.distanceToSquared(pl))[0];
      if (pr) { const c = new THREE.Color(pr.color); P[10].copy(pr.pos); C[10].set(c.r * 1.6, c.g * 1.6, c.b * 1.6); R[10] = 5; }
    }
    this.flashL = Math.max(0, this.flashL - 0.03);
    if (this.flashL > 0) { P[11].set(pl.x, 4, pl.z); C[11].set(this.flashL * 2, this.flashL * 2, this.flashL * 2.4); R[11] = 25; }
  }

  private emitHud() {
    const pl = this.player, b = this.boss;
    this.ev.onHud({
      hp: Math.ceil(pl.hp), maxHp: Math.round(pl.stats.maxHp), gold: this.gold, score: this.score, floor: this.floor, kills: this.kills,
      spell: pl.spell, spellMax: pl.stats.spellMax, dodge: 1 - pl.dodgeCd / pl.stats.dodgeCd, combo: this.combo,
      left: this.enemies.alive.length,
      boss: b && b.awake && b.dying <= 0 ? { name: b.def.name, hp: Math.max(0, b.hp), max: b.maxHp } : null,
    });
  }

  // ---------------- Render ----------------
  private loop = () => {
    this.raf = requestAnimationFrame(this.loop);
    const rd = this.clock.getDelta(); const dt = Math.min(0.05, rd);
    this.update(dt);
    this.shake = Math.max(0, this.shake - dt * 2.2);
    const s = this.shake * this.shake * 0.8;
    const look = tmp2.copy(this.camTarget).add(tmp.set((Math.random() - 0.5) * s, 0.8 + (Math.random() - 0.5) * s, (Math.random() - 0.5) * s));
    this.camera.position.copy(look).addScaledVector(CAM_DIR, 60);
    this.camera.lookAt(look);
    this.renderer.render(this.scene, this.camera);
  };

  private resize() {
    const w = Math.max(1, this.host.clientWidth), h = Math.max(1, this.host.clientHeight), a = w / h;
    this.renderer.setSize(w, h, false);
    this.renderer.domElement.style.width = '100%'; this.renderer.domElement.style.height = '100%';
    this.viewH = a < 1 ? 15 / a : 17;
    const c = this.camera;
    c.left = -this.viewH * a / 2; c.right = this.viewH * a / 2; c.top = this.viewH / 2; c.bottom = -this.viewH / 2;
    c.updateProjectionMatrix();
    this.fx.setScale(h * this.renderer.getPixelRatio() / this.viewH);
  }

  dispose() {
    cancelAnimationFrame(this.raf);
    this.ro.disconnect();
    this.input.dispose();
    this.enemies.dispose(); this.loot.dispose(); this.fx.dispose(); this.player.dispose();
    this.dungeon?.dispose();
    Object.values(this.tex).forEach(t => t.dispose());
    disposeModelCache();
    this.player.rig.mats.forEach(m => m.dispose());
    this.renderer.dispose();
    this.renderer.domElement.remove();
  }
}

export const TILE_SIZE = TILE;

// Efectos: partículas aditivas (Points), sombras de contacto, anillos de aviso y destellos.
import * as THREE from 'three';
import { lin, radialTexture } from './three-compat';

const N = 700;

export class Fx {
  readonly group = new THREE.Group();
  private geo = new THREE.BufferGeometry();
  private pos = new Float32Array(N * 3);
  private col = new Float32Array(N * 3);
  private size = new Float32Array(N);
  private alpha = new Float32Array(N);
  private vel = new Float32Array(N * 3);
  private life = new Float32Array(N);
  private max = new Float32Array(N);
  private grav = new Float32Array(N);
  private base = new Float32Array(N);
  private cursor = 0;
  private mat: THREE.ShaderMaterial;
  private shadowGeo = new THREE.PlaneGeometry(1, 1);
  private shadowMat: THREE.MeshBasicMaterial;
  private ringGeo = new THREE.RingGeometry(0.86, 1, 40);
  private rings: Array<{ m: THREE.Mesh; t: number; dur: number; r: number; grow: boolean }> = [];
  private flashTex = radialTexture([[0, 'rgba(255,255,255,1)'], [0.3, 'rgba(255,255,255,0.45)'], [1, 'rgba(255,255,255,0)']], 128);
  private flashes: Array<{ s: THREE.Sprite; t: number; dur: number; size: number }> = [];

  constructor() {
    this.geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
    this.geo.setAttribute('aColor', new THREE.BufferAttribute(this.col, 3));
    this.geo.setAttribute('aSize', new THREE.BufferAttribute(this.size, 1));
    this.geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alpha, 1));
    this.mat = new THREE.ShaderMaterial({
      uniforms: { uScale: { value: 30 } },
      vertexShader: `attribute vec3 aColor; attribute float aSize; attribute float aAlpha; uniform float uScale;
        varying vec3 vC; varying float vA;
        void main(){ vC = aColor; vA = aAlpha; gl_PointSize = aSize * uScale; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
      fragmentShader: `varying vec3 vC; varying float vA;
        void main(){ vec2 p = gl_PointCoord - 0.5; float d = length(p) * 2.0; if (d > 1.0) discard;
          float a = (1.0 - d) * (1.0 - d) * vA; gl_FragColor = vec4(vC * a, 1.0); }`,
      blending: THREE.AdditiveBlending, depthWrite: false, transparent: true,
    });
    const pts = new THREE.Points(this.geo, this.mat);
    pts.frustumCulled = false; pts.renderOrder = 5;
    this.group.add(pts);
    const shadowTex = radialTexture([[0, 'rgba(0,0,0,0.75)'], [0.6, 'rgba(0,0,0,0.35)'], [1, 'rgba(0,0,0,0)']], 64);
    this.shadowMat = new THREE.MeshBasicMaterial({ map: shadowTex, transparent: true, depthWrite: false });
    this.shadowGeo.rotateX(-Math.PI / 2);
    this.ringGeo.rotateX(-Math.PI / 2);
  }

  setScale(pxPerUnit: number) { this.mat.uniforms.uScale.value = pxPerUnit; }

  /** Emite partículas. color en hex de pantalla; velocidades en unidades/s. */
  spawn(x: number, y: number, z: number, n: number, color: string, speed = 4, life = 0.6, size = 0.35, opts: { up?: number; grav?: number; spread?: number } = {}) {
    const c = new THREE.Color(color);
    for (let k = 0; k < n; k++) {
      const i = this.cursor; this.cursor = (this.cursor + 1) % N;
      const sp = opts.spread ?? 0.2;
      this.pos[i * 3] = x + (Math.random() - 0.5) * sp; this.pos[i * 3 + 1] = y + (Math.random() - 0.5) * sp; this.pos[i * 3 + 2] = z + (Math.random() - 0.5) * sp;
      const a = Math.random() * Math.PI * 2, s = speed * (0.35 + Math.random() * 0.65);
      this.vel[i * 3] = Math.cos(a) * s; this.vel[i * 3 + 1] = (opts.up ?? 0.6) * speed * Math.random(); this.vel[i * 3 + 2] = Math.sin(a) * s;
      const v = 0.75 + Math.random() * 0.25;
      this.col[i * 3] = c.r * v; this.col[i * 3 + 1] = c.g * v; this.col[i * 3 + 2] = c.b * v;
      this.max[i] = this.life[i] = life * (0.6 + Math.random() * 0.4);
      this.base[i] = size * (0.6 + Math.random() * 0.6);
      this.grav[i] = opts.grav ?? 6;
    }
  }

  hit(x: number, z: number, color: string, big = false) {
    this.spawn(x, 1, z, big ? 26 : 14, color, big ? 7 : 5, 0.5, big ? 0.5 : 0.35);
    this.spawn(x, 1, z, 6, '#fff3d0', 3, 0.25, 0.45, { up: 0.2, grav: 0 });
  }
  embers(x: number, y: number, z: number, color = '#ff8a2a') { this.spawn(x, y, z, 1, color, 0.6, 1.2, 0.22, { up: 2, grav: -1.2, spread: 0.5 }); }

  shadow(radius: number) {
    const m = new THREE.Mesh(this.shadowGeo, this.shadowMat);
    m.scale.set(radius * 2.4, 1, radius * 2.4); m.position.y = 0.02; m.renderOrder = 1;
    return m;
  }

  /** Anillo en el suelo: aviso de ataque (grow=true crece hasta r) u onda expansiva. */
  ring(x: number, z: number, r: number, dur: number, color: string, grow = false) {
    let slot = this.rings.find(q => q.t >= q.dur);
    if (!slot) {
      if (this.rings.length >= 16) return;
      const m = new THREE.Mesh(this.ringGeo, new THREE.MeshBasicMaterial({ transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide }));
      m.renderOrder = 4; this.group.add(m);
      slot = { m, t: 0, dur: 1, r: 1, grow: false }; this.rings.push(slot);
    }
    (slot.m.material as THREE.MeshBasicMaterial).color.copy(lin(color));
    slot.m.position.set(x, 0.05, z); slot.t = 0; slot.dur = dur; slot.r = r; slot.grow = grow; slot.m.visible = true;
  }

  flash(x: number, y: number, z: number, size: number, color: string, dur = 0.3) {
    let slot = this.flashes.find(f => f.t >= f.dur);
    if (!slot) {
      if (this.flashes.length >= 12) return;
      const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.flashTex, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true }));
      s.renderOrder = 6; this.group.add(s);
      slot = { s, t: 0, dur, size }; this.flashes.push(slot);
    }
    slot.s.material.color.copy(lin(color)); slot.s.position.set(x, y, z);
    slot.t = 0; slot.dur = dur; slot.size = size; slot.s.visible = true;
  }

  update(dt: number) {
    for (let i = 0; i < N; i++) {
      if (this.life[i] <= 0) { this.alpha[i] = 0; continue; }
      this.life[i] -= dt;
      const k = Math.max(0, this.life[i] / this.max[i]);
      this.vel[i * 3 + 1] -= this.grav[i] * dt;
      this.pos[i * 3] += this.vel[i * 3] * dt; this.pos[i * 3 + 1] += this.vel[i * 3 + 1] * dt; this.pos[i * 3 + 2] += this.vel[i * 3 + 2] * dt;
      if (this.pos[i * 3 + 1] < 0.05) { this.pos[i * 3 + 1] = 0.05; this.vel[i * 3 + 1] *= -0.3; this.vel[i * 3] *= 0.7; this.vel[i * 3 + 2] *= 0.7; }
      this.alpha[i] = k; this.size[i] = this.base[i] * (0.4 + 0.6 * k);
    }
    for (const a of ['position', 'aColor', 'aSize', 'aAlpha']) (this.geo.getAttribute(a) as THREE.BufferAttribute).needsUpdate = true;
    for (const r of this.rings) {
      if (r.t >= r.dur) { r.m.visible = false; continue; }
      r.t += dt; const k = Math.min(1, r.t / r.dur);
      const s = r.grow ? r.r * (0.15 + 0.85 * k) : r.r * (0.3 + 0.7 * Math.sqrt(k));
      r.m.scale.set(s, 1, s);
      (r.m.material as THREE.MeshBasicMaterial).opacity = r.grow ? 0.35 + 0.6 * k : 1 - k;
    }
    for (const f of this.flashes) {
      if (f.t >= f.dur) { f.s.visible = false; continue; }
      f.t += dt; const k = Math.min(1, f.t / f.dur);
      f.s.scale.setScalar(f.size * (0.6 + 0.6 * k)); f.s.material.opacity = 1 - k;
    }
  }

  clear() {
    this.life.fill(0); this.alpha.fill(0);
    this.rings.forEach(r => { r.t = r.dur; r.m.visible = false; });
    this.flashes.forEach(f => { f.t = f.dur; f.s.visible = false; });
  }

  dispose() {
    this.geo.dispose(); this.mat.dispose(); this.shadowGeo.dispose(); this.shadowMat.map?.dispose(); this.shadowMat.dispose();
    this.ringGeo.dispose(); this.rings.forEach(r => (r.m.material as THREE.Material).dispose());
    this.flashTex.dispose(); this.flashes.forEach(f => f.s.material.dispose());
  }
}

// Entrada: teclado (flechas / WASD) en window + controles táctiles virtuales (joystick y botones).
export interface VirtualPad { x: number; y: number; attack: boolean; dodge: boolean; spell: boolean }

const S = Math.SQRT1_2;

export class Input {
  private keys = new Set<string>();
  readonly virtual: VirtualPad = { x: 0, y: 0, attack: false, dodge: false, spell: false };
  private prev = { attack: false, dodge: false, spell: false };

  private onDown = (e: KeyboardEvent) => {
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space'].includes(e.code)) e.preventDefault();
    this.keys.add(e.code);
  };
  private onUp = (e: KeyboardEvent) => { this.keys.delete(e.code); };
  private onBlur = () => { this.keys.clear(); };

  constructor() {
    window.addEventListener('keydown', this.onDown);
    window.addEventListener('keyup', this.onUp);
    window.addEventListener('blur', this.onBlur);
  }

  private any(...c: string[]) { return c.some(k => this.keys.has(k)); }

  /** Dirección de movimiento en el mundo (cámara isométrica: "arriba" = hacia el fondo de la pantalla). */
  move(): { x: number; z: number } {
    let sx = this.virtual.x, sy = this.virtual.y;
    if (this.any('ArrowRight', 'KeyD')) sx += 1;
    if (this.any('ArrowLeft', 'KeyA')) sx -= 1;
    if (this.any('ArrowUp', 'KeyW')) sy += 1;
    if (this.any('ArrowDown', 'KeyS')) sy -= 1;
    const len = Math.hypot(sx, sy);
    if (len < 0.15) return { x: 0, z: 0 };
    const k = Math.min(1, len) / len;
    sx *= k; sy *= k;
    // derecha de pantalla = (+x, -z), arriba de pantalla = (-x, -z)
    return { x: (sx - sy) * S, z: (-sx - sy) * S };
  }

  private edge(name: 'attack' | 'dodge' | 'spell', now: boolean) {
    const e = now && !this.prev[name];
    this.prev[name] = now;
    return e;
  }
  attackHeld() { return this.virtual.attack || this.any('Space', 'KeyJ', 'KeyZ'); }
  attackPressed() { return this.edge('attack', this.attackHeld()); }
  dodgePressed() { return this.edge('dodge', this.virtual.dodge || this.any('ShiftLeft', 'ShiftRight', 'KeyK', 'KeyX')); }
  spellPressed() { return this.edge('spell', this.virtual.spell || this.any('KeyE', 'KeyL', 'KeyQ')); }

  reset() {
    this.keys.clear();
    Object.assign(this.virtual, { x: 0, y: 0, attack: false, dodge: false, spell: false });
  }

  dispose() {
    window.removeEventListener('keydown', this.onDown);
    window.removeEventListener('keyup', this.onUp);
    window.removeEventListener('blur', this.onBlur);
  }
}

// Botín: monedas, pociones, cristales de maná, cofres de mejora, jarrones rompibles y escalera de descenso.
import * as THREE from 'three';
import { Fx } from './fx';
import { Player } from './player';
import { lin, litMat, LitMaterial, radialTexture } from './three-compat';

export type PickKind = 'gold' | 'potion' | 'crystal';
interface Pickup { kind: PickKind; obj: THREE.Object3D; vel: THREE.Vector3; t: number; value: number }
interface Chest { g: THREE.Group; lid: THREE.Object3D; glow: THREE.Sprite; opened: boolean; open: number }
interface Vase { m: THREE.Mesh; alive: boolean }

export interface LootHooks { gold(v: number): void; heal(v: number): void; crystal(): void; chest(): void }

export class Loot {
  private pickups: Pickup[] = [];
  private chests: Chest[] = [];
  private vases: Vase[] = [];
  private geos: THREE.BufferGeometry[] = [];
  private mats: THREE.Material[] = [];
  private coinGeo: THREE.BufferGeometry; private potGeo: THREE.BufferGeometry; private crysGeo: THREE.BufferGeometry;
  private coinMat: LitMaterial; private potMat: LitMaterial; private crysMat: LitMaterial;
  private vaseGeo: THREE.BufferGeometry; private vaseMat: LitMaterial;
  private chestParts: Array<[THREE.BufferGeometry, LitMaterial]>;
  private glowTex = radialTexture([[0, 'rgba(255,255,255,0.9)'], [0.4, 'rgba(255,255,255,0.25)'], [1, 'rgba(255,255,255,0)']], 64);
  readonly stairs = new THREE.Group();
  private rune: THREE.Mesh;
  stairsActive = false;

  constructor(private group: THREE.Group, private fx: Fx, runeTex: THREE.Texture) {
    const G = <T extends THREE.BufferGeometry>(g: T) => { this.geos.push(g); return g; };
    const M = <T extends THREE.Material>(m: T) => { this.mats.push(m); return m; };
    this.coinGeo = G(new THREE.CylinderGeometry(0.22, 0.22, 0.06, 12).rotateX(Math.PI / 2));
    this.potGeo = G(new THREE.SphereGeometry(0.24, 10, 8));
    this.crysGeo = G(new THREE.OctahedronGeometry(0.3));
    this.coinMat = M(litMat({ color: '#ffd24a', emissive: '#6a4a08' }));
    this.potMat = M(litMat({ color: '#ff3048', emissive: '#7a0818' }));
    this.crysMat = M(litMat({ color: '#b48aff', emissive: '#4a22a0' }));
    this.vaseGeo = G(new THREE.LatheGeometry([[0.0, 0], [0.28, 0.02], [0.38, 0.3], [0.32, 0.62], [0.18, 0.78], [0.22, 0.9], [0.0, 0.9]].map(([x, y]) => new THREE.Vector2(x, y)), 10));
    this.vaseMat = M(litMat({ color: '#a8643a' }));
    this.chestParts = [
      [G(new THREE.BoxGeometry(1.2, 0.6, 0.8)), M(litMat({ color: '#7a4a24' }))],
      [G(new THREE.BoxGeometry(1.26, 0.1, 0.86)), M(litMat({ color: '#e0b04a', emissive: '#3a2604' }))],
    ];
    // Escalera: hueco oscuro, peldaños y runa giratoria
    const pit = new THREE.Mesh(G(new THREE.BoxGeometry(2.6, 0.06, 2.6)), M(new THREE.MeshBasicMaterial({ color: 0x000000 })));
    pit.position.y = 0.02; this.stairs.add(pit);
    const stepMat = M(litMat({ color: '#5a5664' }));
    for (let k = 0; k < 4; k++) {
      const s = new THREE.Mesh(G(new THREE.BoxGeometry(2.2, 0.08, 0.5)), stepMat);
      s.position.set(0, 0.07, -0.9 + k * 0.5); s.scale.x = 1 - k * 0.12; this.stairs.add(s);
    }
    const runeMat = M(new THREE.MeshBasicMaterial({ map: runeTex, color: lin('#7ac8ff'), transparent: true, blending: THREE.AdditiveBlending, depthWrite: false }));
    this.rune = new THREE.Mesh(G(new THREE.PlaneGeometry(4.4, 4.4).rotateX(-Math.PI / 2)), runeMat);
    this.rune.position.y = 0.08; this.rune.renderOrder = 3; this.stairs.add(this.rune);
    const glow = new THREE.Sprite(M(new THREE.SpriteMaterial({ map: this.glowTex, color: lin('#3a9cff'), blending: THREE.AdditiveBlending, depthWrite: false, transparent: true })));
    glow.position.y = 0.8; glow.scale.setScalar(5); this.stairs.add(glow);
    this.stairs.visible = false;
    group.add(this.stairs);
  }

  setStairs(x: number, z: number, active: boolean) { this.stairs.position.set(x, 0, z); this.stairsActive = active; this.stairs.visible = active; }

  drop(kind: PickKind, x: number, z: number, value = 1) {
    const obj = new THREE.Mesh(kind === 'gold' ? this.coinGeo : kind === 'potion' ? this.potGeo : this.crysGeo, kind === 'gold' ? this.coinMat : kind === 'potion' ? this.potMat : this.crysMat);
    obj.position.set(x, 0.6, z);
    const a = Math.random() * Math.PI * 2, s = 1.5 + Math.random() * 2.5;
    this.group.add(obj);
    this.pickups.push({ kind, obj, vel: new THREE.Vector3(Math.cos(a) * s, 4 + Math.random() * 2, Math.sin(a) * s), t: 0, value });
  }

  scatterGold(x: number, z: number, n: number) { for (let k = 0; k < n; k++) this.drop('gold', x, z, 1); }

  addChest(x: number, z: number, rot: number) {
    const g = new THREE.Group(); g.position.set(x, 0, z); g.rotation.y = rot;
    const [[bG, bM], [tG, tM]] = this.chestParts;
    const body = new THREE.Mesh(bG, bM); body.position.y = 0.3; g.add(body);
    const trim = new THREE.Mesh(tG, tM); trim.position.y = 0.45; g.add(trim);
    const lid = new THREE.Group(); lid.position.set(0, 0.6, -0.4); g.add(lid);
    const lidM = new THREE.Mesh(bG, bM); lidM.scale.set(1, 0.4, 1); lidM.position.set(0, 0.12, 0.4); lid.add(lidM);
    const lock = new THREE.Mesh(tG, tM); lock.scale.set(0.15, 2, 0.1); lock.position.set(0, 0, 0.83); lid.add(lock);
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.glowTex, color: lin('#ffc24a'), blending: THREE.AdditiveBlending, depthWrite: false, transparent: true, opacity: 0.6 }));
    glow.position.y = 0.8; glow.scale.setScalar(2.6); g.add(glow);
    this.group.add(g);
    this.chests.push({ g, lid, glow, opened: false, open: 0 });
  }

  addVase(x: number, z: number) {
    const m = new THREE.Mesh(this.vaseGeo, this.vaseMat);
    m.position.set(x, 0, z); m.rotation.y = Math.random() * 6; m.scale.setScalar(0.9 + Math.random() * 0.3);
    this.group.add(m); this.vases.push({ m, alive: true });
  }

  /** Rompe jarrones en el arco de ataque. */
  smash(test: (x: number, z: number) => boolean) {
    let n = 0;
    for (const v of this.vases) {
      if (!v.alive || !test(v.m.position.x, v.m.position.z)) continue;
      v.alive = false; v.m.visible = false; n++;
      const { x, z } = v.m.position;
      this.fx.spawn(x, 0.5, z, 16, '#c87a48', 5, 0.6, 0.3);
      const r = Math.random();
      if (r < 0.15) this.drop('potion', x, z, 25); else if (r < 0.22) this.drop('crystal', x, z); else this.scatterGold(x, z, 1 + Math.floor(Math.random() * 3));
    }
    return n;
  }

  update(dt: number, t: number, pl: Player, h: LootHooks) {
    const pp = pl.pos;
    for (const p of this.pickups) {
      p.t += dt;
      const o = p.obj.position;
      const dx = pp.x - o.x, dz = pp.z - o.z, dist = Math.hypot(dx, dz);
      if (p.t > 0.45 && dist < pl.stats.magnet) {
        const pull = 14 * (1 - dist / (pl.stats.magnet + 0.5)) + 4;
        o.x += dx / dist * pull * dt; o.z += dz / dist * pull * dt; o.y += (1 - o.y) * dt * 6;
      } else {
        p.vel.y -= 18 * dt; o.addScaledVector(p.vel, dt);
        if (o.y < 0.35) { o.y = 0.35; p.vel.y = Math.abs(p.vel.y) * 0.35; p.vel.x *= 0.6; p.vel.z *= 0.6; }
      }
      p.obj.rotation.y += dt * 4; p.obj.rotation.x = p.kind === 'crystal' ? 0 : p.obj.rotation.x;
      if (p.t > 0.3 && dist < pl.radius + 0.5) {
        p.t = -1;
        if (p.kind === 'gold') h.gold(p.value); else if (p.kind === 'potion') h.heal(p.value); else h.crystal();
        this.fx.spawn(o.x, o.y, o.z, 8, p.kind === 'gold' ? '#ffd24a' : p.kind === 'potion' ? '#ff4a6a' : '#b48aff', 3, 0.4, 0.3, { up: 1 });
      }
    }
    this.pickups = this.pickups.filter(p => { if (p.t >= 0) return true; p.obj.parent?.remove(p.obj); return false; });
    for (const c of this.chests) {
      if (!c.opened && Math.hypot(pp.x - c.g.position.x, pp.z - c.g.position.z) < 1.6) {
        c.opened = true; h.chest();
        this.fx.spawn(c.g.position.x, 0.8, c.g.position.z, 30, '#ffd24a', 5, 0.9, 0.4, { up: 1.5 });
        this.fx.flash(c.g.position.x, 1, c.g.position.z, 6, '#ffc24a', 0.5);
      }
      if (c.opened) { c.open = Math.min(1, c.open + dt * 3); c.glow.material.opacity = 0.6 * (1 - c.open); }
      else c.glow.material.opacity = 0.45 + Math.sin(t * 3) * 0.15;
      c.lid.rotation.x = -c.open * 1.9;
    }
    if (this.stairs.visible) {
      this.rune.rotation.y = t * 0.6;
      if (Math.random() < 0.5) this.fx.spawn(this.stairs.position.x + (Math.random() - 0.5) * 2.5, 0.1, this.stairs.position.z + (Math.random() - 0.5) * 2.5, 1, '#5ab0ff', 0.4, 1.4, 0.3, { up: 2.5, grav: -0.5 });
    }
  }

  nearStairs(x: number, z: number) { return this.stairsActive && Math.hypot(x - this.stairs.position.x, z - this.stairs.position.z) < 1.3; }

  clear() {
    this.pickups.forEach(p => p.obj.parent?.remove(p.obj)); this.pickups = [];
    this.chests.forEach(c => { c.g.parent?.remove(c.g); c.glow.material.dispose(); }); this.chests = [];
    this.vases.forEach(v => v.m.parent?.remove(v.m)); this.vases = [];
    this.setStairs(0, 0, false);
  }

  dispose() {
    this.clear();
    this.geos.forEach(g => g.dispose()); this.mats.forEach(m => m.dispose()); this.glowTex.dispose();
  }
}

// Modelos low-poly procedurales: héroe y enemigos (con materiales iluminados por antorchas).
import * as THREE from 'three';
import { EnemyKind } from './config';
import { LitMaterial, litMat } from './three-compat';

const geoCache = new Map<string, THREE.BufferGeometry>();
const G = (key: string, make: () => THREE.BufferGeometry) => {
  let g = geoCache.get(key);
  if (!g) { g = make(); geoCache.set(key, g); }
  return g;
};
export function disposeModelCache() { geoCache.forEach(g => g.dispose()); geoCache.clear(); }

const box = (w: number, h: number, d: number) => G(`b${w},${h},${d}`, () => new THREE.BoxGeometry(w, h, d));
const sph = (r: number, s = 10) => G(`s${r},${s}`, () => new THREE.SphereGeometry(r, s, Math.max(6, s - 3)));
const cyl = (a: number, b: number, h: number, s = 10) => G(`c${a},${b},${h},${s}`, () => new THREE.CylinderGeometry(a, b, h, s));
const cone = (r: number, h: number, s = 10) => G(`k${r},${h},${s}`, () => new THREE.ConeGeometry(r, h, s));

export interface Rig {
  root: THREE.Group; body: THREE.Group;
  mats: LitMaterial[]; baseEmissive: THREE.Vector3[];
  p: Record<string, THREE.Object3D>;
}

class Builder {
  rig: Rig;
  private matByKey = new Map<string, LitMaterial>();
  constructor() {
    const root = new THREE.Group(), body = new THREE.Group();
    root.add(body);
    this.rig = { root, body, mats: [], baseEmissive: [], p: {} };
  }
  mat(color: string, emissive?: string) {
    const k = color + (emissive ?? '');
    let m = this.matByKey.get(k);
    if (!m) {
      m = litMat({ color, emissive });
      this.matByKey.set(k, m); this.rig.mats.push(m);
      this.rig.baseEmissive.push((m.uniforms.uEmissive.value as THREE.Vector3).clone());
    }
    return m;
  }
  add(geo: THREE.BufferGeometry, color: string, x: number, y: number, z: number, parent?: THREE.Object3D, emissive?: string, name?: string) {
    const m = new THREE.Mesh(geo, this.mat(color, emissive));
    m.position.set(x, y, z);
    (parent ?? this.rig.body).add(m);
    if (name) this.rig.p[name] = m;
    return m;
  }
  pivot(name: string, x: number, y: number, z: number, parent?: THREE.Object3D) {
    const g = new THREE.Group(); g.position.set(x, y, z);
    (parent ?? this.rig.body).add(g); this.rig.p[name] = g; return g;
  }
}

export function buildHero(): Rig {
  const b = new Builder();
  const steel = '#aeb6c8', dark = '#3a3442', red = '#b3202e', gold = '#e0b04a';
  for (const s of [-1, 1]) {
    const leg = b.pivot(s < 0 ? 'legL' : 'legR', s * 0.17, 0.72, 0);
    b.add(box(0.22, 0.62, 0.26), dark, 0, -0.33, 0, leg);
    b.add(box(0.24, 0.16, 0.34), '#4a3426', 0, -0.64, 0.04, leg);
  }
  b.add(box(0.72, 0.72, 0.46), steel, 0, 1.12, 0);
  b.add(box(0.5, 0.6, 0.06), red, 0, 1.06, 0.25);
  b.add(box(0.76, 0.1, 0.5), '#5a3a22', 0, 0.8, 0);
  b.add(box(0.14, 0.14, 0.04), gold, 0, 0.8, 0.26);
  const cape = b.add(box(0.7, 0.95, 0.06), '#8a1522', 0, 1.0, -0.28, undefined, undefined, 'cape');
  cape.rotation.x = 0.15;
  b.add(sph(0.3, 12), steel, 0, 1.72, 0);
  b.add(box(0.36, 0.07, 0.1), '#141018', 0, 1.74, 0.25);
  b.add(cone(0.08, 0.5, 6), red, 0, 2.08, -0.05).rotation.x = -0.5;
  for (const s of [-1, 1]) b.add(sph(0.17, 8), steel, s * 0.44, 1.42, 0);
  const arm = b.pivot('arm', 0.46, 1.38, 0);
  b.add(box(0.16, 0.5, 0.16), steel, 0, -0.22, 0, arm);
  const sword = b.pivot('sword', 0, -0.45, 0.05, arm);
  b.add(box(0.07, 0.3, 0.07), '#5a3a22', 0, 0.05, 0, sword);
  b.add(box(0.36, 0.06, 0.08), gold, 0, -0.12, 0, sword);
  b.add(box(0.1, 1.15, 0.05), '#e8eef8', 0, -0.72, 0, sword, '#2a3550');
  arm.rotation.order = 'YXZ';
  const shield = b.pivot('shield', -0.5, 1.12, 0.12);
  b.add(box(0.1, 0.66, 0.52), '#6a3f22', 0, 0, 0, shield);
  b.add(box(0.12, 0.5, 0.12), gold, -0.02, 0, 0, shield);
  b.add(box(0.12, 0.12, 0.38), gold, -0.02, 0, 0, shield);
  return b.rig;
}

export function buildEnemy(kind: EnemyKind): Rig {
  const b = new Builder();
  const eye = (x: number, y: number, z: number, c: string, r = 0.06, parent?: THREE.Object3D) => b.add(sph(r, 6), '#000000', x, y, z, parent, c);
  if (kind === 'skeleton') {
    const bone = '#ddd4bc';
    for (const s of [-1, 1]) {
      const leg = b.pivot(s < 0 ? 'legL' : 'legR', s * 0.15, 0.7, 0);
      b.add(box(0.1, 0.68, 0.1), bone, 0, -0.34, 0, leg);
    }
    b.add(box(0.5, 0.12, 0.3), bone, 0, 0.74, 0);
    b.add(box(0.08, 0.6, 0.08), bone, 0, 1.05, -0.05);
    for (let k = 0; k < 3; k++) b.add(box(0.46 - k * 0.06, 0.06, 0.32), bone, 0, 1.0 + k * 0.14, 0);
    b.add(sph(0.26, 9), bone, 0, 1.6, 0, undefined, undefined, 'head');
    b.add(box(0.26, 0.12, 0.2), bone, 0, 1.44, 0.07);
    eye(-0.09, 1.62, 0.21, '#ff3a1a'); eye(0.09, 1.62, 0.21, '#ff3a1a');
    const arm = b.pivot('arm', 0.32, 1.3, 0);
    b.add(box(0.08, 0.55, 0.08), bone, 0, -0.25, 0, arm);
    const sw = b.pivot('sword', 0, -0.5, 0.05, arm);
    b.add(box(0.08, 0.9, 0.05), '#8a7a6a', 0, -0.45, 0, sw);
    b.add(box(0.26, 0.06, 0.06), '#5a4030', 0, 0, 0, sw);
    const arm2 = b.pivot('arm2', -0.32, 1.3, 0);
    b.add(box(0.08, 0.55, 0.08), bone, 0, -0.25, 0, arm2);
  } else if (kind === 'bat') {
    const body = b.pivot('core', 0, 1.3, 0);
    b.add(sph(0.3, 9), '#3b2446', 0, 0, 0, body);
    b.add(sph(0.2, 8), '#4a2c56', 0, 0.22, 0.12, body);
    for (const s of [-1, 1]) b.add(cone(0.07, 0.2, 5), '#3b2446', s * 0.12, 0.42, 0.1, body);
    eye(-0.08, 0.26, 0.29, '#ffd400', 0.05, body); eye(0.08, 0.26, 0.29, '#ffd400', 0.05, body);
    for (const s of [-1, 1]) {
      const w = b.pivot(s < 0 ? 'wingL' : 'wingR', s * 0.22, 0.05, 0, body);
      b.add(box(0.8, 0.04, 0.5), '#2a1834', s * 0.4, 0, 0, w);
      b.add(box(0.5, 0.04, 0.3), '#2a1834', s * 0.85, 0, -0.1, w);
    }
  } else if (kind === 'warlock') {
    b.add(cone(0.55, 1.5, 10), '#3a1f5a', 0, 0.75, 0);
    b.add(cyl(0.3, 0.38, 0.5, 10), '#2c1646', 0, 1.35, 0);
    b.add(cone(0.3, 0.6, 10), '#2c1646', 0, 1.85, -0.02, undefined, undefined, 'head');
    b.add(sph(0.2, 8), '#0a0610', 0, 1.62, 0.1);
    eye(-0.07, 1.64, 0.27, '#7dff6a', 0.05); eye(0.07, 1.64, 0.27, '#7dff6a', 0.05);
    b.add(box(0.4, 0.5, 0.05), '#c9a64a', 0, 1.0, 0.36);
    const arm = b.pivot('arm', 0.4, 1.3, 0.1);
    b.add(cyl(0.04, 0.04, 1.9, 6), '#4a3020', 0, -0.2, 0, arm);
    b.add(sph(0.16, 8), '#000000', 0, 0.82, 0, arm, '#5dff4a', 'orb');
  } else if (kind === 'golem') {
    const stone = '#6d6670', glow = '#ff7a1a';
    for (const s of [-1, 1]) {
      const leg = b.pivot(s < 0 ? 'legL' : 'legR', s * 0.42, 0.85, 0);
      b.add(box(0.5, 0.85, 0.55), stone, 0, -0.42, 0, leg);
    }
    b.add(box(1.5, 1.1, 0.95), stone, 0, 1.45, 0);
    b.add(box(0.9, 0.5, 0.06), '#000000', 0, 1.5, 0.48, undefined, glow);
    b.add(box(0.65, 0.55, 0.6), stone, 0, 2.25, 0.12, undefined, undefined, 'head');
    b.add(box(0.44, 0.1, 0.06), '#000000', 0, 2.3, 0.43, undefined, glow);
    for (const s of [-1, 1]) {
      const arm = b.pivot(s < 0 ? 'arm2' : 'arm', s * 0.98, 1.8, 0);
      b.add(box(0.5, 1.1, 0.55), stone, 0, -0.5, 0, arm);
      b.add(box(0.62, 0.5, 0.65), '#5a545e', 0, -1.15, 0.05, arm);
    }
  } else {
    // Rey Liche (jefe)
    const robe = '#1d2a3a', bone = '#e6dfc8', gold = '#e8b84a';
    b.add(cone(1.0, 2.4, 12), robe, 0, 1.2, 0);
    b.add(cyl(0.55, 0.7, 0.8, 12), '#243548', 0, 2.3, 0);
    b.add(box(1.6, 0.25, 0.7), '#2e4058', 0, 2.65, 0);
    b.add(sph(0.42, 12), bone, 0, 3.15, 0, undefined, undefined, 'head');
    b.add(box(0.4, 0.18, 0.3), bone, 0, 2.92, 0.12);
    eye(-0.15, 3.18, 0.36, '#4af0ff', 0.09); eye(0.15, 3.18, 0.36, '#4af0ff', 0.09);
    const crown = b.pivot('crown', 0, 3.5, 0);
    b.add(cyl(0.38, 0.4, 0.2, 10), gold, 0, 0, 0, crown);
    for (let k = 0; k < 6; k++) { const a = k / 6 * Math.PI * 2; b.add(cone(0.08, 0.3, 4), gold, Math.cos(a) * 0.34, 0.22, Math.sin(a) * 0.34, crown); }
    b.add(box(0.7, 1.1, 0.08), '#000000', 0, 1.9, 0.62, undefined, '#164a66');
    const arm = b.pivot('arm', 0.95, 2.55, 0);
    b.add(box(0.2, 0.9, 0.2), robe, 0, -0.4, 0.1, arm);
    b.add(cyl(0.06, 0.06, 3.0, 6), '#2a2028', 0, -0.2, 0.3, arm);
    b.add(sph(0.26, 10), '#000000', 0, 1.4, 0.3, arm, '#3ad8ff', 'orb');
    const arm2 = b.pivot('arm2', -0.95, 2.55, 0);
    b.add(box(0.2, 0.9, 0.2), robe, 0, -0.4, 0.1, arm2);
    const orbit = b.pivot('orbit', 0, 1.8, 0);
    for (let k = 0; k < 3; k++) { const a = k / 3 * Math.PI * 2; b.add(sph(0.18, 8), '#000000', Math.cos(a) * 1.7, 0, Math.sin(a) * 1.7, orbit, '#2ab8ff'); }
  }
  return b.rig;
}

/** Destello de golpe y tinte de aviso (rojo) sobre todos los materiales del rig. */
export function setRigFx(rig: Rig, flash: number, warn: number) {
  rig.mats.forEach((m, i) => {
    m.uniforms.uFlash.value = flash;
    const e = m.uniforms.uEmissive.value as THREE.Vector3, b = rig.baseEmissive[i];
    e.set(b.x + warn * 0.55, b.y + warn * 0.05, b.z + warn * 0.02);
  });
}

export function disposeRig(rig: Rig) {
  rig.root.parent?.remove(rig.root);
  rig.mats.forEach(m => m.dispose());
}

// Héroe: movimiento, ataque con espada en arco, esquiva con invulnerabilidad y animación.
import * as THREE from 'three';
import { Stats } from './config';
import { Dungeon } from './dungeon';
import { buildHero, Rig, setRigFx } from './models';
import { lin } from './three-compat';

export const ATTACK_ARC = 2.3;
export const ATTACK_RANGE = 2.6;
const SWING_T = 0.2;

export class Player {
  rig: Rig;
  stats: Stats;
  hp: number;
  facing = 0;
  private targetFacing = 0;
  radius = 0.5;
  atkCd = 0; swing = 0; swingSide = 1;
  dodgeT = 0; dodgeCd = 0; invuln = 0;
  private dodgeDir = new THREE.Vector3();
  spell = 2;
  flash = 0;
  private walk = 0;
  private moving = 0;
  readonly slash: THREE.Mesh;
  private slashMat: THREE.MeshBasicMaterial;

  constructor(stats: Stats, private shadow: THREE.Object3D) {
    this.stats = stats; this.hp = stats.maxHp; this.spell = stats.spellMax;
    this.rig = buildHero();
    this.rig.root.add(shadow);
    const arc = new THREE.RingGeometry(0.7, ATTACK_RANGE, 24, 1, -Math.PI / 2 - ATTACK_ARC / 2, ATTACK_ARC);
    arc.rotateX(-Math.PI / 2);
    this.slashMat = new THREE.MeshBasicMaterial({ color: lin('#cfe4ff'), transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });
    this.slash = new THREE.Mesh(arc, this.slashMat);
    this.slash.position.y = 1.0; this.slash.renderOrder = 4;
    this.rig.root.add(this.slash);
  }

  get pos() { return this.rig.root.position; }
  get dodging() { return this.dodgeT > 0; }
  get vulnerable() { return this.invuln <= 0 && this.dodgeT <= 0; }

  reset(stats: Stats, x: number, z: number) {
    this.stats = stats; this.hp = stats.maxHp; this.spell = stats.spellMax;
    this.pos.set(x, 0, z); this.facing = this.targetFacing = Math.PI * 1.25;
    this.atkCd = this.swing = this.dodgeT = this.dodgeCd = this.invuln = this.flash = 0;
    this.rig.root.visible = true; this.rig.body.rotation.set(0, 0, 0); this.rig.body.position.set(0, 0, 0);
  }

  face(dx: number, dz: number, instant = false) {
    if (Math.abs(dx) + Math.abs(dz) < 1e-4) return;
    this.targetFacing = Math.atan2(dx, dz);
    if (instant) this.facing = this.targetFacing;
  }

  forward(out: THREE.Vector3) { return out.set(Math.sin(this.facing), 0, Math.cos(this.facing)); }

  tryAttack() {
    if (this.atkCd > 0 || this.dodgeT > 0) return false;
    this.atkCd = this.stats.atkCd; this.swing = SWING_T; this.swingSide *= -1;
    return true;
  }

  tryDodge(mx: number, mz: number) {
    if (this.dodgeCd > 0 || this.dodgeT > 0) return false;
    if (Math.abs(mx) + Math.abs(mz) < 0.1) { mx = Math.sin(this.facing); mz = Math.cos(this.facing); }
    this.dodgeDir.set(mx, 0, mz).normalize();
    this.face(mx, mz, true);
    this.dodgeT = 0.32; this.dodgeCd = this.stats.dodgeCd; this.invuln = 0.4;
    return true;
  }

  hurt(dmg: number) {
    if (!this.vulnerable) return false;
    this.hp = Math.max(0, this.hp - dmg); this.invuln = 0.7; this.flash = 1;
    return true;
  }

  heal(v: number) { this.hp = Math.min(this.stats.maxHp, this.hp + v); }

  update(dt: number, mx: number, mz: number, d: Dungeon, t: number) {
    this.atkCd = Math.max(0, this.atkCd - dt); this.dodgeCd = Math.max(0, this.dodgeCd - dt);
    this.invuln = Math.max(0, this.invuln - dt); this.flash = Math.max(0, this.flash - dt * 4);
    const p = this.pos;
    if (this.dodgeT > 0) {
      this.dodgeT -= dt;
      p.x += this.dodgeDir.x * 15 * dt; p.z += this.dodgeDir.z * 15 * dt;
      const k = 1 - Math.max(0, this.dodgeT) / 0.32;
      this.rig.body.rotation.x = k * Math.PI * 2; this.rig.body.position.y = Math.sin(k * Math.PI) * 0.5 - 0.1;
      if (this.dodgeT <= 0) { this.rig.body.rotation.x = 0; this.rig.body.position.y = 0; }
    } else {
      const sp = this.stats.speed * (this.swing > 0 ? 0.55 : 1);
      p.x += mx * sp * dt; p.z += mz * sp * dt;
      if (this.swing <= 0) this.face(mx, mz);
    }
    d.collide(p, this.radius);
    // giro suave
    let da = this.targetFacing - this.facing;
    da = Math.atan2(Math.sin(da), Math.cos(da));
    this.facing += da * Math.min(1, dt * 16);
    this.rig.root.rotation.y = this.facing;
    // animación
    const mv = Math.min(1, Math.hypot(mx, mz));
    this.moving += (mv - this.moving) * Math.min(1, dt * 10);
    this.walk += dt * 11 * this.moving;
    const s = Math.sin(this.walk) * 0.7 * this.moving, P = this.rig.p;
    P.legL.rotation.x = s; P.legR.rotation.x = -s;
    if (this.dodgeT <= 0) this.rig.body.position.y = Math.abs(Math.cos(this.walk)) * 0.08 * this.moving + Math.sin(t * 2) * 0.015;
    P.cape.rotation.x = 0.15 + this.moving * 0.35 + Math.sin(this.walk * 0.5) * 0.05;
    P.shield.rotation.y = -0.2;
    if (this.swing > 0) {
      this.swing -= dt;
      const k = 1 - Math.max(0, this.swing) / SWING_T;
      const e = 1 - (1 - k) * (1 - k);
      P.arm.rotation.set(-Math.PI / 2 + 0.25, this.swingSide * (1.3 - e * 2.6), 0);
      this.slashMat.opacity = Math.sin(k * Math.PI) * 0.75;
      this.slash.scale.set(this.swingSide, 1, 1);
    } else {
      this.slashMat.opacity *= 0.5;
      P.arm.rotation.x += (-0.5 - s * 0.4 - P.arm.rotation.x) * Math.min(1, dt * 12);
      P.arm.rotation.y += (0 - P.arm.rotation.y) * Math.min(1, dt * 12);
    }
    const blink = this.invuln > 0 && this.dodgeT <= 0 ? (Math.sin(t * 40) > 0 ? 0.25 : 0) : 0;
    setRigFx(this.rig, Math.max(this.flash, blink), 0);
  }

  dispose() { this.slash.geometry.dispose(); this.slashMat.dispose(); }
}

import * as THREE from 'three';

// r170 trae gestión de color y r128 no: la desactivamos y linealizamos a mano con lin() → mismo resultado en ambas.
const CM = (THREE as any).ColorManagement;
if (CM && typeof CM.enabled === 'boolean') CM.enabled = false;
/** Color sRGB (#hex) → lineal para materiales integrados (sprites, básicos). */
export const lin = (c: string | THREE.Color) => new THREE.Color(c).convertSRGBToLinear();

/** Multiplica TODAS las intensidades de luz (r155+ usa unidades físicas). La iluminación del juego es propia (shader). */
export const LIGHT_K = Number(THREE.REVISION) >= 155 ? Math.PI : 1;

export function setupRenderer(r: THREE.WebGLRenderer) {
  const a = r as any; const T = THREE as any;
  if ('outputColorSpace' in a) a.outputColorSpace = T.SRGBColorSpace; else a.outputEncoding = T.sRGBEncoding;
}

export function srgbTexture(t: THREE.Texture) {
  const a = t as any; const T = THREE as any;
  if ('colorSpace' in a) a.colorSpace = T.SRGBColorSpace; else a.encoding = T.sRGBEncoding;
  return t;
}

/** Textura desde un canvas 2D. `srgb=false` → datos crudos (para el shader propio, que decodifica a mano). */
export function canvasTexture(w: number, h: number, draw: (g: CanvasRenderingContext2D) => void, srgb = true) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  draw(c.getContext('2d')!);
  const t = new THREE.CanvasTexture(c);
  t.wrapS = THREE.RepeatWrapping; t.wrapT = THREE.RepeatWrapping; t.anisotropy = 4;
  return srgb ? srgbTexture(t) : t;
}

export function radialTexture(stops: Array<[number, string]>, size = 64) {
  return canvasTexture(size, size, g => {
    const h = size / 2, gr = g.createRadialGradient(h, h, 0, h, h, h);
    stops.forEach(([o, c]) => gr.addColorStop(o, c));
    g.fillStyle = gr; g.fillRect(0, 0, size, size);
  });
}

// ---------- Iluminación propia: idéntica en r128 y r170 (no depende de los modelos de luz de cada versión) ----------
export const MAX_LIGHTS = 12;
export const lightUniforms = {
  uLP: { value: Array.from({ length: MAX_LIGHTS }, () => new THREE.Vector3(0, -99, 0)) },
  uLC: { value: Array.from({ length: MAX_LIGHTS }, () => new THREE.Vector3()) },
  uLR: { value: new Array<number>(MAX_LIGHTS).fill(1) },
  uAmb: { value: new THREE.Vector3(0.035, 0.03, 0.06) },
};

const VERT = /* glsl */`
varying vec3 vW; varying vec3 vN; varying vec3 vTint;
#ifdef MESH_UV
varying vec2 vUv;
#endif
#ifdef USE_TINT
attribute vec3 aTint;
#endif
void main() {
#ifdef MESH_UV
  vUv = uv;
#endif
  vec4 p = vec4(position, 1.0); vec3 n = normal;
#ifdef USE_INSTANCING
  p = instanceMatrix * p; n = mat3(instanceMatrix) * n;
#endif
  vec4 w = modelMatrix * p;
  vW = w.xyz; vN = normalize(mat3(modelMatrix) * n);
#ifdef USE_TINT
  vTint = aTint;
#else
  vTint = vec3(1.0);
#endif
  gl_Position = projectionMatrix * viewMatrix * w;
}`;

const FRAG = /* glsl */`
#define NL ${MAX_LIGHTS}
uniform vec3 uLP[NL]; uniform vec3 uLC[NL]; uniform float uLR[NL];
uniform vec3 uAmb; uniform vec3 uColor; uniform vec3 uEmissive; uniform float uFlash; uniform float uUV;
#ifdef USE_MAP
uniform sampler2D uMap;
#endif
#ifdef MESH_UV
varying vec2 vUv;
#endif
varying vec3 vW; varying vec3 vN; varying vec3 vTint;
void main() {
  vec3 base = uColor * vTint;
  vec3 N = normalize(vN);
#ifdef USE_MAP
#ifdef MESH_UV
  vec2 uv = vUv;
#else
  vec3 an = abs(N);
  vec2 uv = (an.y > 0.5 ? vW.xz : (an.x > 0.5 ? vW.zy : vW.xy)) * uUV;
#endif
  vec3 t = texture2D(uMap, uv).rgb;
  base *= t * t;
#endif
  vec3 L = uAmb * (0.55 + 0.45 * max(N.y, 0.0));
  for (int i = 0; i < NL; i++) {
    vec3 d = uLP[i] - vW; float dist = length(d);
    float a = clamp(1.0 - dist / uLR[i], 0.0, 1.0); a *= a;
    float nd = max(dot(N, d / max(dist, 0.001)), 0.0) * 0.85 + 0.15;
    L += uLC[i] * a * nd;
  }
  vec3 col = base * L + uEmissive + uFlash * vec3(1.0, 0.85, 0.7);
  col = col / (1.0 + col * 0.22);
  gl_FragColor = vec4(pow(col, vec3(0.4545)), 1.0);
}`;

export interface LitOpts { color: string; map?: THREE.Texture; meshUv?: boolean; uv?: number; emissive?: string; tint?: boolean; side?: THREE.Side }
const toLin = (hex: string) => { const c = lin(hex); return new THREE.Vector3(c.r, c.g, c.b); };

/** Material con la iluminación de antorchas de la mazmorra (soporta InstancedMesh y tinte por instancia). */
export function litMat(o: LitOpts) {
  const defines: Record<string, string> = {};
  if (o.map) defines.USE_MAP = '';
  if (o.tint) defines.USE_TINT = '';
  if (o.meshUv) defines.MESH_UV = '';
  const m = new THREE.ShaderMaterial({
    vertexShader: VERT, fragmentShader: FRAG, defines, side: o.side ?? THREE.FrontSide,
    uniforms: {
      ...lightUniforms,
      uColor: { value: toLin(o.color) },
      uEmissive: { value: o.emissive ? toLin(o.emissive) : new THREE.Vector3() },
      uFlash: { value: 0 },
      uUV: { value: o.uv ?? 0.5 },
      uMap: { value: o.map ?? null },
    },
  });
  return m;
}
export type LitMaterial = ReturnType<typeof litMat>;
